(window.RAGHIB = window.RAGHIB || {})["2-5"] = [
  {"a": [126, 126], "h": "\"Make this a secure land, and provide its people with fruits\" — a prayer for a city in a barren valley", "hAr": "﴿رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ﴾ — دعاءٌ لمدينةٍ في وادٍ قفر", "said": "ولما بنى إبراهيم عليه السلام البيت في قفر، ومن شرط المدن أن يتحرى في بنائها موضع يمكن أن يجري فيه نهر أو يشق فيه قناة، ويتخذ فيه مزرعة تفي بمطاعم قطانها، وعلم أن لا قوام لهم إلا بأن تجنى إليهم الثمرات، ولا يمكن جني الثمرات إليهم إلا بأمنه، سأل الله عز وجل - أن يجعله بلدا آمنا بسياسة إلاهية وأن يرزق أهله بتسخير الناس لجبي الثمرات إليه ولما سأله لهم الرزق، وكان قد سمع في جواب سؤاله الإمامة لذريته ما سمع تدارك سؤاله فقيده وقال: ﴿مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ﴾ فقال تعالى: ﴿وَمَن كَفَرَ﴾ تنبيها أن رحمته في الدنيا وسعت كل شيء، وأن نعمه فيها متاحة للكل ليجعلوها ذريعة إلى إدراك ثوابه، ثم من كفر وضيع النعم فمسوق إلى عذابه", "en": "Ibrahim built the House in a barren place. A city normally needs a site where a river can run or a canal be dug, and farmland enough to feed its people. He knew they could only live if fruits were brought to them from elsewhere — and fruits could only be brought if the place was safe. So he asked Allah to make it a secure land by His own governance, and to provide for its people by moving others to bring the fruits of the world to it.\nAnd he had just heard the answer to his prayer for his descendants' leadership — \"My covenant does not reach the wrongdoers\" — so this time he corrected himself and limited the prayer: \"those of them who believe in Allah and the Last Day\". Allah answered: \"And whoever disbelieves too\" — a reminder that His mercy in this world embraces everything, and His blessings here are open to all, so that they may use them as a road to His reward; whoever disbelieves and wastes the blessings is then driven to His punishment.", "ar": "بنى إبراهيم البيت في قفر، ومن شرط المدن أن يُتحرّى في بنائها موضعٌ يجري فيه نهرٌ أو تُشقّ فيه قناة، وتُتّخذ فيه مزرعةٌ تفي بمطاعم سكّانها؛ فعلم أنه لا قوام لهم إلا بأن تُجلب إليهم الثمرات، ولا يمكن ذلك إلا بأمنه، فسأل الله أن يجعله بلدًا آمنًا بسياسةٍ إلهيّة، وأن يرزق أهله بتسخير الناس لجلب الثمرات إليه.\nولمّا كان قد سمع في جواب سؤاله الإمامة لذرّيته ما سمع — ﴿لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾ — تدارك سؤاله هنا فقيّده: ﴿مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ﴾، فقال تعالى: ﴿وَمَن كَفَرَ﴾ — تنبيهًا أن رحمته في الدنيا وسعت كلّ شيء، ونعمه فيها متاحةٌ للكلّ ليجعلوها ذريعةً إلى ثوابه، ثم من كفر وضيّع النعم فمسوقٌ إلى عذابه.", "links": [{"ref": "14:37", "q": "﴿رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ﴾", "en": "The barren valley", "ar": "الوادي غير ذي الزرع"}, {"ref": "28:57", "q": "﴿أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا﴾", "en": "The prayer answered: fruits of everything brought to it", "ar": "الدعاء مستجابًا: تُجبى إليه ثمرات كلّ شيء"}, {"ref": "2:124", "q": "﴿لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾", "en": "What he had just heard", "ar": "ما سمعه قبلُ"}, {"ref": "17:20", "q": "﴿كُلّٗا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ﴾", "en": "Worldly giving reaches everyone", "ar": "عطاء الدنيا يعمّ الجميع"}], "v": 1, "p": 313, "pe": 313, "sid": 314},
  {"a": [126, 126], "h": "\"I will let him enjoy a little\" — the finite beside the infinite", "hAr": "﴿فَأُمَتِّعُهُۥ قَلِيلٗا﴾ — المتناهي بجانب ما لا يتناهى", "said": "والاضطرار: حمل الإنسان على [ما يضره وهو في التعارف] حمل على الأمر بكره وذلك على وجهين: أحدهما بسبب خارج ... والثاني بسبب من داخل، وذلك إما بقهر قوة له لا يناله بدفعها الهلاك، كمن غلب عليه شهوة خمر أو قمار، وإما بقهر قوة يناله بدفعها الهلاك كمن اشتد به الجوع، فاضطر إلى أكل الميتة ... إن قيل: إن قوله (فأمتعه) يقتضي كثرة ثبات الفعل وقوله (قليلا) ينافيه، فكيف جمع بينهما؟ قيل: ذلك على وجهين، فإن نعمته في الدنيا وإن كانت كثيرة بإضافة بعضها إلى بعض، فقليلة بإضافتها إلى نعمة الآخرة، وعلى هذا قال: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾، كيف لا يقل ما يتناهى بالإضافة إلى ما لا يتناهى؟", "en": "\"I will let him enjoy\" suggests plenty — so how can it be \"a little\"? Because His blessings in this world, however many when counted against each other, are few when set beside the blessings of the Hereafter: \"say: the enjoyment of this world is little\". How could what has an end not be little beside what has no end?\n\"Then I will force him to the punishment of the Fire\": idtirar is being driven to something against one's will. It comes from outside — being beaten or threatened into it, or physically made to do it — or from inside: either a force one could resist without perishing, like a craving for wine or gambling that overpowers someone; or a force one cannot resist without perishing, like hunger so severe that it drives a person to eat carrion.", "ar": "﴿فَأُمَتِّعُهُۥ﴾ يقتضي كثرة، و﴿قَلِيلٗا﴾ ينافيه، فكيف جُمع بينهما؟ قيل: نِعَمُه في الدنيا وإن كثرت بإضافة بعضها إلى بعض، فهي قليلةٌ بإضافتها إلى نعيم الآخرة، وعلى هذا قال: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾؛ وكيف لا يقلّ ما يتناهى بالإضافة إلى ما لا يتناهى؟\nو﴿ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ﴾: «الاضطرار» الحمل على الأمر كُرهًا، وهو ضربان: بسببٍ من خارج — كأن يُضرب أو يُهدَّد حتى يفعل، أو يُؤخذ بيده فيُفعل به —، وبسببٍ من داخل: إمّا بقهر قوّةٍ لا يناله بدفعها الهلاك — كمن غلبته شهوة خمرٍ أو قمار —، وإمّا بقهر قوّةٍ يناله بدفعها الهلاك — كمن اشتدّ به الجوع فاضطرّ إلى أكل الميتة.", "links": [{"ref": "4:77", "q": "﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ﴾", "en": "The little beside the lasting", "ar": "القليل بجانب الباقي"}, {"ref": "2:173", "q": "﴿فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ﴾", "en": "The necessity the law excuses — the hungry man's", "ar": "الاضطرار الذي يعذر به الشرع — اضطرار الجائع"}], "v": 1, "p": 312, "pe": 313, "sid": 313},
  {"a": [127, 127], "h": "Raising the foundations of the House — of stone, and of honour", "hAr": "﴿وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ﴾ — قواعد البناء وقواعد الشرف", "said": "وقيل إن إبراهيم عليه السلام - كان يبني وإسماعيل يرفع إليه الأحجار ويناوله، وذلك لا يمنع من أن يكون الفعل منسوبا إليهما ... وما اختلف فيه أنه هل كان للبيت بناء قبل إبراهيم - عليه السلام -، فأعاده أو هو الذي أنشأه وأحدثه، فليس مما يفتقر معنى الآية إليه وقيل ليس يعنى برفعهما قواعد البناء فقط، بل ... تشريفه بدعاء الناس إليه ودعاء الله بحفظه، وصح نسبة ذلك إليهما وإن كان الله تعالى في الحقيقة شرفه من حيث أنهما من الأسباب المتأخرة لتشريفه", "en": "Qawa'id, \"foundations\", comes from qu'ud, sitting — that is, being settled and firm.\nIt is said that Ibrahim built while Isma'il lifted the stones up and handed them to him; that does not stop the act from being credited to both. (Someone who insisted each must have laid part himself for the verse to be true has not understood how wide language is.) As for whether the House had a building before Ibrahim which he restored, or whether he founded it, the meaning of the verse does not depend on it.\nAnd some said the \"raising\" is not only of the building's foundations but of its honour: by calling people to it and praying to Allah to protect it. It is credited to them, though in truth Allah honoured it, because they were the near causes of that honour.", "ar": "«القواعد» من القعود بمعنى الثبات.\nوقيل: كان إبراهيم يبني وإسماعيل يرفع إليه الحجارة ويناوله، وذلك لا يمنع أن يُنسب الفعل إليهما؛ وقول من أوجب أن يتولّى كلٌّ منهما البناء مرّةً ليصحّ النسبة إليهما بعيدٌ، لسعة مجال الألفاظ. وأمّا الخلاف: هل كان للبيت بناءٌ قبل إبراهيم فأعاده، أو هو الذي أنشأه؟ فليس ممّا يفتقر إليه معنى الآية.\nوقيل: ليس المراد رفع قواعد البناء فقط، بل رفع شرفه بدعاء الناس إليه ودعاء الله بحفظه؛ وصحّت نسبته إليهما وإن كان الله في الحقيقة هو الذي شرّفه، لأنهما من الأسباب المتأخّرة لتشريفه.", "links": [{"ref": "22:26", "q": "﴿وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ﴾", "en": "The place shown to him", "ar": "المكان الذي بُوِّئ له"}, {"ref": "3:96", "q": "﴿إِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا﴾", "en": "The first house set up for people", "ar": "أوّل بيتٍ وُضع للناس"}, {"ref": "22:27", "q": "﴿وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا﴾", "en": "Raising its honour: calling people to it", "ar": "رفع شرفه: دعاء الناس إليه"}], "v": 1, "p": 314, "pe": 314, "sid": 315},
  {"a": [128, 128], "h": "\"Make us Muslims to You\" — the Islam asked for by a prophet", "hAr": "﴿رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ﴾ — الإسلام الذي يسأله نبيّ", "said": "النسك: غاية العبادة، والناسك الآخذ نفسه ببلوغ قاصيتها حسب طاقته ... ولم يعن بالمسلم ههنا من حقن دمه بالشهادتين، كما ظن بعضهم وقال هذا دعاء بما علم كونه لهما لا محالة، وإنما عنى من ليس في قلبه تعظيم [غير] الله معه، وهو المعنى بالمضروب له المثل في قوله: ﴿وَرَجُلٗا سَلَمٗا لِّرَجُلٍ﴾ وبقوله: ﴿إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ﴾ وقوله: ﴿تَوَفَّنِي مُسۡلِمٗا﴾ وهذه قاصية الإيمان، ونبه تعالى بالآية أن من حق الإنسان أن يكون مع تحري الحق لا ينفك من التضرع إلى الله - عز وجل - بإرشاده وتوفيقه", "en": "Nusuk is worship at its utmost; a nasik is one who holds himself to reaching its farthest point as far as he can. The acts of Hajj are called manasik, and later the word was narrowed to the sacrifice.\nWhy would Ibrahim and Isma'il pray to be made Muslims — were they not already? Some thought this was praying for what they knew they had. Ar-Raghib: \"Muslim\" here is not someone whose life is protected by saying the two testimonies; it is someone in whose heart nothing is revered alongside Allah — the man in the parable \"a man belonging wholly to one master\", the one who \"comes to Allah with a sound heart\", the one Yusuf meant by \"take my soul as a Muslim\". That is the farthest reach of faith.\nAnd the verse teaches that a person, even while seeking the truth with all his effort, should never stop begging Allah humbly for guidance and success — and asking Him to forgive a sin he may have committed without noticing: \"and accept our repentance\".", "ar": "«النُّسك» غاية العبادة، و«الناسك» الآخذ نفسه ببلوغ قاصيتها حسب طاقته؛ وسُمّيت أعمال الحجّ «المناسك»، ثم خُصّ النسك بالذبيحة.\nولم يُرد بـ«المسلم» هنا من حقن دمه بالشهادتين — كما ظنّ بعضهم فقال: هذا دعاءٌ بما عُلم أنه حاصلٌ لهما —، وإنما عنى من ليس في قلبه تعظيمُ غير الله معه: وهو المضروب له المثل في ﴿وَرَجُلٗا سَلَمٗا لِّرَجُلٍ﴾، والمعنيّ بـ﴿إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ﴾، وبقول يوسف: ﴿تَوَفَّنِي مُسۡلِمٗا﴾؛ وهذه قاصية الإيمان.\nونبّه بالآية أن من حقّ الإنسان — مع تحرّيه الحقّ — ألّا ينفكّ من التضرّع إلى الله بإرشاده وتوفيقه، وأن يسأله التوبة من ذنبٍ عسى أن يكون منه وهو غافلٌ عنه: ﴿وَتُبۡ عَلَيۡنَآۖ﴾.", "links": [{"ref": "39:29", "q": "﴿ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ﴾", "en": "The heart that belongs to One", "ar": "القلب الذي لواحد"}, {"ref": "26:89", "q": "﴿إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ﴾", "en": "The sound heart", "ar": "القلب السليم"}, {"ref": "2:131", "q": "﴿إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾", "en": "The same Islam, a few verses later", "ar": "الإسلام نفسه بعد آيات"}], "v": 1, "p": 315, "pe": 315, "sid": 316},
  {"a": [128, 128], "h": "\"And of our descendants a nation\" — why not all of them: the world needs every calling", "hAr": "﴿وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ﴾ — لماذا لم يعمّم: الدنيا تحتاج كلّ الحِرَف", "said": "فإن قيل: ولم قيد؟ فقال: ﴿وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ﴾ ولم يعمم؟ قيل إن هذه منزلة شريفة لا يكاد يتخصص بها إلا الواحد فالواحد في برهة بعد برهة، وعلم أن الحكمة الإلاهية لا تقتضي ذلك، فإنه لو جعل الناس كلهم كذلك لما تمشى أمر العالم إذ كان العالم يفتقر إلى كون أفاضل فيها وأوساط وأراذل لتولي عمارته والقيام بتمشية أموره فقد قيل: عمارة الدنيا بثلاثة أشياء، أحدها الزراعة والغرس، والثاني: في الحماية والحرب، والثالث جلب الأشياء من مصر إلى مصر، وأنبياء الله لا يصلحون لذلك إذ كانوا بغرض آخر أشرف من ذلك ولهذا قيل: \" لولا الحمقى لخربت الدنيا \" وإنما عني بالحمقى المعنيون بأمر الدنيا بإضافته إلى المعنيين بأمر الآخرة، ولذلك قال ﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾", "en": "Why did Ibrahim say \"and of our descendants a nation submitting to You\", and not \"all our descendants\"? Ar-Raghib: this is so noble a rank that hardly anyone reaches it — one person, then another, age after age — and Ibrahim knew that divine wisdom does not call for everyone to be like that.\nIf all people were like that, the world's affairs would not run. The world needs people of every level — the eminent, the middling, and the humble — to take on its building and keep its affairs going. It has been said that the building of the world rests on three things: farming and planting; protection and defence; and carrying goods from city to city — and Allah's prophets are not made for that work, since they exist for another, nobler purpose. Hence the saying, \"were it not for the fools, the world would fall to ruin\" — \"fools\" meaning those absorbed in worldly work, compared with those absorbed in the Hereafter.\nThat is why Allah says \"He… settled you in it (ista'marakum)\": building and cultivating the earth is itself one of the purposes He created people for.", "ar": "لماذا قيّد فقال ﴿وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ﴾ ولم يعمّم؟ قال الراغب: هذه منزلةٌ شريفة لا يكاد يختصّ بها إلا الواحد بعد الواحد في برهةٍ بعد برهة، وعلم إبراهيم أن الحكمة الإلهيّة لا تقتضي أن يكون الناس كلّهم كذلك.\nفلو جُعل الناس كلّهم كذلك لما تمشّى أمر العالم؛ إذ العالم يفتقر إلى أن يكون فيه أفاضل وأوساطٌ وأراذل، ليتولّوا عمارته والقيام بتمشية أموره. وقد قيل: عمارة الدنيا بثلاثة أشياء: الزراعة والغرس، والحماية والحرب، وجلب الأشياء من مصرٍ إلى مصر؛ وأنبياء الله لا يصلحون لذلك إذ كانوا لغرضٍ آخر أشرف منه. ولهذا قيل: «لولا الحمقى لخربت الدنيا»، والمراد بالحمقى المعنيّون بأمر الدنيا بالإضافة إلى المعنيّين بأمر الآخرة.\nولذلك قال: ﴿هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾ — فعمارة الأرض من المقاصد التي خُلق لها الناس.", "links": [{"ref": "11:61", "q": "﴿هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾", "en": "Building the earth — a purpose of creation", "ar": "عمارة الأرض من مقاصد الخلق"}, {"ref": "43:32", "q": "﴿وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ﴾", "en": "Ranks, so that people serve one another", "ar": "درجاتٌ ليخدم الناس بعضهم بعضًا"}, {"ref": "10:14", "q": "﴿ثُمَّ جَعَلۡنَٰكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ﴾", "en": "Successors on earth, being watched", "ar": "خلائف في الأرض لينظر كيف نعمل"}], "v": 1, "p": 315, "pe": 315, "sid": 316},
  {"a": [129, 129], "h": "\"Send among them a messenger\" — \"I am the prayer of my father Ibrahim\"; and why this order", "hAr": "﴿وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ﴾ — «أنا دعوة أبي إبراهيم»، ووجه الترتيب", "said": "فأما الرسول- الذي طلبه إبراهيم- عليه السلام، فقد روي عن نبينا - صلى الله عليه وسلم - أنه قال: \" أنا دعوة أبي إبراهيم وبشارة عيسى بن مريم \" يعني بالأول: قوله: ﴿وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ﴾، وبالآخر: قوله: ﴿وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ﴾. إن قيل: كيف قال: يتلو عليهم آياتك ويعلمهم الكتاب والحكمة وليس الكتاب إلا الآيات، وما وجه هذا الترتيب؟ قيل: أما الآيات فهي الآيات الدالة على معجزة النبي - صلى الله عليه وسلم - ... وأما الترتيب فلأن أول منزلة النبي - صلى الله عليه وسلم - بعد ادعاء النبوة الإتيان بالآيات الدالة على نبوته، ثم بعده تعليمهم الكتاب، أي تعريفهم حقائقه لا ألفاظه فقط، ثم بتعليمهم الكتاب يوصلهم إلى إفادة الحكمة وهي أشرف منزلة العلم، ولهذا قال: ﴿وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ﴾، ثم بالتدرج في الحكمة يصير الإنسان مزكى، أي مطهرا مستصلحا لمجاورة الله- عز وجل-", "en": "The messenger Ibrahim asked for is our Prophet ﷺ, who is reported to have said: \"I am the prayer of my father Ibrahim, and the glad tidings of 'Isa son of Maryam\" — the prayer being \"send among them a messenger from among them\", the glad tidings \"a messenger who will come after me, whose name is Ahmad\".\nWhy \"recite Your signs to them AND teach them the Book\" — is the Book not the signs? And why this order? The \"signs\" are the proofs of his prophethood, and \"recite\" is used because the greatest proof of his prophethood is bound up with the Quran. Then the order climbs: a prophet's first stage is to bring the signs that prove him; then to teach the Book — its realities, not only its words; then through the Book he brings them to wisdom, the highest rank of knowledge (\"whoever is given wisdom has been given much good\"); and by rising step by step in wisdom a person becomes purified — cleansed and made fit to be near Allah.\nHikmah has been defined by its start — knowing the realities of things, human and divine — or by its end — preparing oneself through knowledge and action to reach Allah's reward.", "ar": "الرسول الذي طلبه إبراهيم هو نبيّنا ﷺ، فقد رُوي عنه أنه قال: «أنا دعوة أبي إبراهيم، وبشارة عيسى ابن مريم»؛ يعني بالأولى ﴿وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ﴾، وبالأخرى ﴿وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ﴾.\nفإن قيل: كيف قال ﴿يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ﴾ وليس الكتاب إلا الآيات؟ وما وجه الترتيب؟ قيل: «الآيات» هنا الدالّة على نبوّته، وذكر التلاوة لأن أعظم دلالة نبوّته متعلّقٌ بالقرآن. وأمّا الترتيب: فأوّل منزلة النبيّ بعد ادّعاء النبوّة الإتيان بالآيات الدالّة عليها، ثم تعليمهم الكتاب — تعريفهم حقائقه لا ألفاظه فقط —، ثم بتعليم الكتاب يوصلهم إلى الحكمة، وهي أشرف منازل العلم: ﴿وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ﴾؛ ثم بالتدرّج في الحكمة يصير الإنسان مزكًّى، أي مطهّرًا مستصلَحًا لمجاورة الله.\nو«الحكمة» حُدّت باعتبار مبدئها: معرفة حقائق الأشياء الإنسيّة والإلهيّة؛ وباعتبار منتهاها: الترشّح بالعلم والعمل لإدراك ثواب الله.", "links": [{"ref": "61:6", "q": "﴿وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ﴾", "en": "The glad tidings of 'Isa", "ar": "بشارة عيسى"}, {"ref": "2:151", "q": "﴿كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ﴾", "en": "The prayer answered — with purifying placed before teaching", "ar": "الدعاء مستجابًا — والتزكية قُدّمت على التعليم"}, {"ref": "2:269", "q": "﴿وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ﴾", "en": "Wisdom: the highest rank of knowledge", "ar": "الحكمة أشرف منازل العلم"}], "v": 1, "p": 316, "pe": 317, "sid": 317},
  {"a": [130, 130], "h": "\"Who turns away from Ibrahim's way, but one who fools himself?\" — know yourself, and you will know your Maker", "hAr": "﴿إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ﴾ — من عرف نفسه عرف صانعه", "said": "وسفه نفسه أبلغ من جهلها، وذاك أن الجهل ضربان جهل بسيط، وهو أن لا يكون للإنسان اعتقاد في الشيء وجهل مركب، وهو أن يعتقد في الحق أنه باطل، وفي الباطل أنه حق، والسفه أن يعتمد ذلك، ويتحرى بالفعل مقتضى ما اعتقده، فبين تعالى أن من رغب عن ملة إبراهيم، فإن ذلك لسفهه نفسه، وذلك أعظم مذمة، فهو مبدأ لكل نقيصة، وذاك أن من جهل نفسه جهل أنه مصنوع، وإذا جهل كونه مصنوعا جهل صانعه، وإذا لم يعلم أن له صانعا، فكيف يعرف أمره ونهيه، وما حسنه وقبحه، ولكون معرفتها ذريعة إلى معرفة الخالق- جل ثناؤه- قال: ﴿وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ﴾، وقال: ﴿وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ﴾", "en": "Raghbah is a wide, eager wanting; \"raghiba 'an\", with \"from\", turns that wanting away — to renounce. Istifa' is taking the pure essence (safwah) of a thing, as ikhtiyar is taking its best.\n\"Fooling oneself\" is worse than being ignorant of oneself. Ignorance is of two kinds: simple — having no belief about a thing; and compound — believing the true false and the false true. Safah, foolishness, is to rely on that compound ignorance and act on it.\nSo whoever turns away from Ibrahim's religion does it out of fooling himself — the gravest blame, because it is the beginning of every failing: whoever does not know himself does not know that he was made; whoever does not know he was made does not know his Maker; and whoever does not know he has a Maker — how will he know His commands and prohibitions, what is good and what is ugly? Because knowing oneself is the road to knowing the Creator, Allah said \"and in yourselves — do you not see?\", and \"do not be like those who forgot Allah, so He made them forget themselves\".", "ar": "«الرغبة» سعة الإرادة، فإذا عُدّيت بـ«عن» اقتضت صرف الإرادة عن الشيء والزهد فيه. و«الاصطفاء» تناول صفوة الشيء، كما أن الاختيار تناول خيره.\nو﴿سَفِهَ نَفۡسَهُۥۚ﴾ أبلغ من «جهلها»: فالجهل ضربان: بسيط — ألّا يكون للإنسان اعتقادٌ في الشيء —، ومركّب — أن يعتقد في الحقّ أنه باطل وفي الباطل أنه حقّ —؛ والسفه أن يعتمد ذلك ويتحرّى بالفعل مقتضى ما اعتقده.\nفبيّن أن من رغب عن ملّة إبراهيم فلسفهه نفسه، وذلك أعظم مذمّة، فهو مبدأ كلّ نقيصة: فمن جهل نفسه جهل أنه مصنوع، ومن جهل أنه مصنوعٌ جهل صانعه، ومن لم يعلم أن له صانعًا فكيف يعرف أمره ونهيه وما حسّنه وما قبّحه؟ ولكون معرفة النفس ذريعةً إلى معرفة الخالق قال: ﴿وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ﴾، وقال: ﴿وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ﴾.", "links": [{"ref": "51:21", "q": "﴿وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ﴾", "en": "Knowing oneself — the road to the Maker", "ar": "معرفة النفس طريقٌ إلى الصانع"}, {"ref": "59:19", "q": "﴿وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ﴾", "en": "Forgetting Allah, forgetting oneself", "ar": "نسيان الله ونسيان النفس"}, {"ref": "60:4", "q": "﴿قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ﴾", "en": "Ibrahim — the example not to turn from", "ar": "إبراهيم — القدوة التي لا يُرغب عنها"}], "v": 1, "p": 317, "pe": 317, "sid": 318},
  {"a": [130, 130], "h": "\"Chosen in this world, righteous in the Hereafter\" — why not the other way round?", "hAr": "﴿ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ﴾ — لماذا لم يُعكس؟", "said": "فإن قيل: كيف وصفه بالاصطفاء في الدنيا وبالصلاح في الآخرة، والنظر يقتضي عكس ذلك، فإن الصلاح وصف يرجع إلى الفعل، وذلك يكون في الدنيا، والاصطفاء حال يستحقه العبد بكونه صالحا، فحقه أن يكون في الآخرة؟ قيل الاصطفاء ضربان، أحدهما كما قلت والآخر في الدنيا، وهو اختصاص الله بعض العبيد بولايته ونبوته لخصوصيته فيه وهو المعنى بقوله ﴿شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ﴾ ... وفي الجملة، فإن الصالح هو الخارج عن حد الرذيلة، وليس في الدنيا على الإطلاق بكل نظر صالح، بل عامة ما فيه يمكن أن يوصف بفاسد بها إما حالة ما أو بنظر ما، فإذن الصلاح المطلق في الآخرة، فلهذا خص بها", "en": "A sharp question: righteousness belongs to deeds, and deeds are done in this world; being chosen is a state one earns by being righteous, so it should belong to the next. Why then \"chosen in this world\" and \"righteous in the Hereafter\"?\nAr-Raghib: being chosen is of two kinds — the one you describe, and another in this world: Allah singling out some servants for His friendship and prophethood because of a quality He placed in them — \"grateful for His favours, He chose him\". And righteousness, though it is measured by the states of this world, is repaid in the Hereafter.\nOther readings: \"in the Hereafter\" may mean \"among those who do the deeds of the Hereafter\"; or \"this world\" is his life and \"the Hereafter\" what comes after his death — the good name he prayed for: \"grant me an honourable mention among later generations\"; or, since people are three — those who wrong themselves, the moderate, and those who race ahead — \"the righteous\" here names those who race ahead.\nAnd in sum: the righteous is one who has left the bounds of vice. Nothing in this world is righteous absolutely and from every angle; almost anything here can be called corrupt in some state or from some angle. Absolute righteousness belongs to the Hereafter — so it was named there.", "ar": "فإن قيل: الصلاح وصفٌ يرجع إلى الفعل وذلك في الدنيا، والاصطفاء حالٌ يستحقّها العبد بصلاحه فحقّه أن يكون في الآخرة، فلماذا عكس؟ قيل: الاصطفاء ضربان: أحدهما كما قلت، والآخر في الدنيا، وهو اختصاص الله بعض عباده بولايته ونبوّته لخصوصيّةٍ فيه، وهو المعنيّ بقوله: ﴿شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ﴾؛ والصلاح وإن اعتُبر بأحوال الدنيا فمُجازًى به في الآخرة.\nوجُوّز أن يكون ﴿فِي ٱلۡأٓخِرَةِ﴾ أي في أعمال الآخرة؛ أو أن «الدنيا» حال حياته و«الآخرة» ما بعد وفاته، ويكون صلاحه الثناء الحسن الذي سأله: ﴿وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ﴾؛ أو أنه لمّا كان الناس ثلاثة — ظالمٌ ومقتصدٌ وسابق — عبّر عن السابق بالصالح.\nوفي الجملة: الصالح هو الخارج عن حدّ الرذيلة، وليس في الدنيا صالحٌ على الإطلاق وبكلّ نظر، بل عامّة ما فيها يمكن أن يوصف بالفساد في حالٍ ما أو بنظرٍ ما؛ فالصلاح المطلق في الآخرة، فلهذا خُصّ بها.", "links": [{"ref": "16:121", "q": "﴿شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ﴾", "en": "Chosen in this world", "ar": "الاصطفاء في الدنيا"}, {"ref": "26:84", "q": "﴿وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ﴾", "en": "The good name he asked for", "ar": "الثناء الحسن الذي سأله"}, {"ref": "35:32", "q": "﴿فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ﴾", "en": "The three kinds of people", "ar": "الأصناف الثلاثة"}], "v": 1, "p": 317, "pe": 318, "sid": 318},
  {"a": [131, 131], "h": "\"Submit\" — \"I submit\": to be Allah's captive is to be free", "hAr": "﴿أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ﴾ — من أسره الرحمن فهو الحرّ", "said": "لما سأل الله تعالى بقوله: ﴿وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ﴾، أجابه بقوله تعالى: \" أسلم \" أي أخلص سرك فإنه موضع الاطلاع ... وبقوله: \" الأعمال بالنيات \" ... وقيل معنى \" أسلم \" استأسر له كقولك للأسير: استسلم، وقيل: معناه: اجعل نفسك مسلمة عن أسر الشيطان ... وهذان القولان واحد في الحقيقة فإن من أسره الرحمن فاستأسر له فهو الحر المطلق عن عبادة غيره، وقد قيل: \" لن تكون عبدا لله حقا حتى لا تكون لما دونه مسترقا \"، وإلى ذلك أشار بقوله: ﴿وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا﴾", "en": "Ibrahim had prayed \"make us Muslims to You\"; this is the answer: \"Submit\" — make your inner self sincere, for that is the place Allah looks upon. The Prophet ﷺ pointed to it: \"actions are only by intentions\"; and the Quran: \"they were commanded only to worship Allah, sincere to Him in religion\".\nTwo other readings: \"submit\" as a captive surrenders to his captor; or \"keep yourself safe from the captivity of Satan\", who vowed to lead all astray \"except Your sincere servants\". Ar-Raghib: the two are one in reality. Whoever the Most Merciful takes captive, and who surrenders to Him, is the one who is absolutely free — free from serving anything else. As it has been said: \"you will not be a true servant of Allah until you are enslaved to nothing below Him\" — which is what \"let him not associate anyone in the worship of his Lord\" points to.\n\"I submit\" answers the command: a pledge that he stood ready for whatever would be asked of him — and Allah urges us to follow him in it.", "ar": "سأل إبراهيم: ﴿وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ﴾، فأجابه: «أسلِم» — أي أخلص سرّك، فإنه موضع اطّلاع الله؛ وإليه أشار النبي ﷺ بقوله: «إنما الأعمال بالنيات»، وقال تعالى: ﴿وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾.\nوقيل: «أسلِم» استأسِر له، كما يُقال للأسير: استسلم؛ وقيل: اجعل نفسك سالمةً من أسر الشيطان الذي قال: ﴿لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ۝ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾. قال الراغب: والقولان واحدٌ في الحقيقة: فمن أسره الرحمن فاستأسر له فهو الحرّ المطلق عن عبادة غيره؛ وقد قيل: «لن تكون عبدًا لله حقًّا حتى لا تكون لما دونه مسترَقًّا»، وإليه أشار بقوله: ﴿وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا﴾.\nو﴿أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾ مبنيٌّ على الأوّل: كأنه وعدٌ منه أنه متأهّبٌ لما يُراد منه، وقد حثّنا الله على الاقتداء به في الاستسلام له.", "links": [{"ref": "98:5", "q": "﴿وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾", "en": "Sincerity — the heart of \"submit\"", "ar": "الإخلاص — لبّ «أسلم»"}, {"ref": "38:82-83", "q": "﴿لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ۝ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾", "en": "The captivity of Satan, and who escapes it", "ar": "أسر الشيطان ومن ينجو منه"}, {"ref": "15:42", "q": "﴿إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ﴾", "en": "Allah's servants are out of Satan's reach", "ar": "عباد الله لا سلطان للشيطان عليهم"}, {"ref": "18:110", "q": "﴿فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا﴾", "en": "Enslaved to nothing below Him", "ar": "لا يُسترَقّ لما دونه"}], "v": 1, "p": 318, "pe": 319, "sid": 319},
  {"a": [132, 132], "h": "\"Do not die except as Muslims\" — not a ban on dying, but a call to the Islam that gives life", "hAr": "﴿فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ﴾ — ليس نهيًا عن الموت، بل حثٌّ على الإسلام الذي يُحيي", "said": "الوصية: التقدم إلى الغير بما يعمل به مقترنا بوعظ ... وقوله: [بها] أي بالملة، وقيل بالكلمة التي دل عليها قوله: \" أسلمت \"، وكلاهما غير منفك من الآخر، إذ كانت هذه الكلمة من جملة الملة، والملة مقتضية لهذه الكلمة ... وحث على الإسلام، أي أسلموا قبل أن تموتوا، وليس ذلك نهيا عن الموت، وإنما هو حث على الإسلام المتقدم ذكره فهو الذي يفيد الحياة الأبدية المذكورة في قوله: ﴿وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ﴾", "en": "Wasiyyah, \"enjoining\", is putting before someone what he should do, joined with admonition; it comes from \"wasahu\", he joined it, whose opposite is \"qasahu\", he cut it off.\n\"Ibrahim enjoined IT on his sons\": the religion — or the word \"I submit\" just before. The two cannot be separated: the word is part of the religion, and the religion requires the word. And Ya'qub enjoined his sons with it just as Ibrahim had: \"Allah has chosen for you the religion\".\n\"So do not die except as Muslims\" is not a prohibition of dying — no one controls that. It urges the Islam just described: be Muslims before death comes, for that Islam is what brings the everlasting life of which Allah says \"do not think those killed in Allah's way are dead; they are alive with their Lord, provided for\".", "ar": "«الوصيّة» التقدّم إلى الغير بما يعمل به مقترنًا بوعظ، واشتقاقها من «وصاه» أي وصله، وضدّه «قصاه» أي فصله.\nو«بها»: بالملّة، أو بالكلمة التي دلّ عليها قوله ﴿أَسۡلَمۡتُ﴾؛ وكلاهما لا ينفكّ عن الآخر: فالكلمة من جملة الملّة، والملّة مقتضيةٌ للكلمة. ووصّى يعقوب بنيه بها كما وصّى إبراهيم: ﴿إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ﴾.\nو﴿فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ﴾ ليس نهيًا عن الموت، وإنما هو حثٌّ على الإسلام المذكور — أسلموا قبل أن تموتوا —، فهو الذي يفيد الحياة الأبدية المذكورة في قوله: ﴿وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ﴾.", "links": [{"ref": "43:28", "q": "﴿وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ﴾", "en": "The word that stayed in his line", "ar": "الكلمة الباقية في عقبه"}, {"ref": "3:102", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ﴾", "en": "The same charge, given to us", "ar": "الوصيّة نفسها لنا"}, {"ref": "3:169", "q": "﴿وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ﴾", "en": "The life this Islam brings", "ar": "الحياة التي يفيدها هذا الإسلام"}], "v": 1, "p": 319, "pe": 319, "sid": 320},
  {"a": [133, 133], "h": "\"What will you worship after me?\" — Ya'qub feared the world for them, not idols", "hAr": "﴿مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ﴾ — خاف يعقوب عليهم الدنيا لا الأصنام", "said": "لم يعن بقوله: ﴿مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ﴾ العبادة المشروعة فقط، وإنما عنى جميع الأعمال، وكأنه دعاهم أن لا يتحروا في أعمالهم غير وجه الله - عز وجل- ولم يخف عليهم الاشتغال بعبادة الأصنام، وإنما خاف أن تشغلهم دنياهم، ولهذا قيل: \" ما قطعك عن الله فهو طاغوت \"، ولهذا قال: ﴿وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ﴾، أي نخدم ما دون الله", "en": "Shuhud, \"witnessing\", is being present — in person, in care, or in word.\nOn his deathbed Ya'qub asked, \"what will you worship after me?\" Ar-Raghib: he did not mean only the acts of worship the law prescribes; he meant ALL their deeds — as if calling them to seek nothing in anything they did but the Face of Allah. He was not afraid they would turn to idols; he was afraid their worldly life would absorb them. Hence the saying: \"whatever cuts you off from Allah is a taghut (a false god)\". And hence Ibrahim's prayer, \"keep me and my sons away from worshipping idols\" — that is, from serving anything other than Allah. The poet meant this kind of \"worship\": \"a young man who mastered pleasures lest they enslave him — and not everyone who holds them is their master\".", "ar": "«الشهود» حضورٌ بالذات أو بالعناية أو بالمقال.\nو﴿مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ﴾: لم يعنِ العبادة المشروعة فقط، بل جميع الأعمال، فكأنه دعاهم ألّا يتحرّوا في أعمالهم غير وجه الله. ولم يخف عليهم عبادة الأصنام، وإنما خاف أن تشغلهم دنياهم؛ ولهذا قيل: «ما قطعك عن الله فهو طاغوت»، ولهذا قال إبراهيم: ﴿وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ﴾ أي أن نخدم ما دون الله. وهذا المعنى تحرّاه الشاعر في العبادة: «فتًى ملك اللذّاتِ أن تستعبدَنْه — وما كلُّ ذي مِلكٍ لهنّ بمالكِ».", "links": [{"ref": "14:35", "q": "﴿وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ﴾", "en": "Every idol — including the world", "ar": "كلّ صنمٍ — والدنيا منها"}, {"ref": "45:23", "q": "﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾", "en": "\"Whatever cuts you off from Allah…\"", "ar": "«ما قطعك عن الله فهو طاغوت»"}, {"ref": "36:60", "q": "﴿أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ﴾", "en": "\"Worship\" as obedience", "ar": "العبادة بمعنى الطاعة"}], "v": 1, "p": 320, "pe": 320, "sid": 321},
  {"a": [133, 133], "h": "\"Your God and the God of your fathers… One God\" — and Isma'il counted among the \"fathers\"", "hAr": "﴿إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ﴾ … ﴿إِلَٰهٗا وَٰحِدٗا﴾ — وإسماعيل معدودٌ في «الآباء»", "said": "والثاني من حيث المعنى، وهو أن المعبود لما لم يمكن سبيل إلى الوصول إليه إلا بالنظر ... بينوا أن معبودنا هو الواحد الذي أثبته، وأثبته آباؤك ... وفهم الجملة أن تسميتها بالأب ليس بمنكر، بل قد يسمى [كل] كبير من الأجانب أبا على أن الأعمام والأجداد إذا كانوا مع الأب فتسميتهم بالآباء أقرب، كتسمية الشمس مع القمر قمرين", "en": "Why \"your God and the God of your fathers\", repeating \"God\", as if there were two? First, grammar: Arabic cannot join a noun to a pronoun in that position without repeating the word it depends on. Second, meaning: the One who is worshipped can only be reached through reflection, so his sons made clear that the One they worship is the very One whom Ya'qub affirmed and whom his fathers affirmed — then removed any doubt: \"One God, and to Him we submit\".\nIsma'il was Ya'qub's uncle, yet he is named among his \"fathers\". That is no strain on the language: any elder can be called father, even a stranger; and uncles and grandfathers named together with a father are all the more naturally \"fathers\" — as the sun and the moon together are called \"the two moons\".", "ar": "لماذا قالوا ﴿إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ﴾ فكرّروا اللفظ كأنهما اثنان؟ من جهة اللفظ: المضاف إلى الضمير لا يُعطف عليه إلا بإعادة المضاف. ومن جهة المعنى: المعبود لا سبيل إلى الوصول إليه إلا بالنظر، فبيّنوا أن معبودهم هو الواحد الذي أثبته يعقوب وأثبته آباؤه، ثم أزالوا الشبهة بقولهم: ﴿إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ﴾.\nوإسماعيل عمّ يعقوب، وقد عُدّ في آبائه؛ وليس ذلك بمنكر: فقد يُسمّى كلّ كبيرٍ — حتى من الأجانب — أبًا، على أن الأعمام والأجداد إذا ذُكروا مع الأب فتسميتهم بالآباء أقرب، كتسمية الشمس مع القمر «قمرين».", "links": [{"ref": "12:38", "q": "﴿وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ﴾", "en": "Yusuf also calls his forefathers \"my fathers\"", "ar": "يوسف يسمّي أجداده «آبائي»"}], "v": 1, "p": 320, "pe": 321, "sid": 321},
  {"a": [134, 134], "h": "\"That was a nation which has passed\" — no one is paid for another's deeds", "hAr": "﴿تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ﴾ — لا يُجزى أحدٌ بعمل غيره", "said": "وقوله: ﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ﴾ أي جمع في نفسه في الفضيلة ما لا يجتمع إلا في أمة ... والكسب: اجتلاب النفع بالعمل، وإذا قيل في المضرة، فعلى طريق التشبيه ... أن أعمالهم وأعمالكم متباينة لا يثاب ولا يعاقب أحد بما كان من الآخر كقوله: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾، وليس معنى بقوله: ﴿وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ﴾ السؤال المجرد، فقد أخبر أنه يقول لعيسى بن مريم ﴿ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ﴾ إنما يعني المؤاخذة بها", "en": "Ummah first meant \"that which is aimed at\"; a community is an ummah because people head toward it, and a religion because a community gathers on it. \"Ibrahim was an ummah\": he gathered in himself such virtue as is otherwise found only in a whole nation — as the poet said, \"it is not beyond Allah to gather the whole world in one man\".\nKasb, \"earning\", is bringing benefit through work; said of harm only by analogy.\nHaving shown that they had not truly followed Ibrahim, Allah makes clear that their deeds and yours are separate: no one is rewarded or punished for what another did — \"no bearer of burdens bears the burden of another\". Being descended from prophets saves no one.\n\"You will not be asked about what they did\" does not mean no question is ever put — Allah will ask 'Isa himself, \"did you tell people, 'take me and my mother as gods'?\" It means you will not be held to account for their deeds.", "ar": "«الأمّة» في الأصل المقصود، وسُمّيت الجماعة أمّةً لأن الفِرَق تؤمّها، والدين أمّةً لأن الجماعة عليه. و﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ﴾: جمع في نفسه من الفضيلة ما لا يجتمع إلا في أمّة، كقول الشاعر: «وليس على الله بمستنكَرٍ — أن يجمع العالَم في واحد».\nو«الكسب» اجتلاب النفع بالعمل، ويُقال في المضرّة على التشبيه.\nثم بيّن أن أعمالهم وأعمالكم متباينة، لا يُثاب أحدٌ ولا يُعاقَب بما كان من غيره: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾ — فلا يُنجي أحدًا نسبُه إلى الأنبياء.\nو﴿وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ﴾ ليس نفيًا للسؤال المجرّد، فقد أخبر أنه يسأل عيسى: ﴿ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ﴾؛ وإنما المعنى المؤاخذة بها.", "links": [{"ref": "16:120", "q": "﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا﴾", "en": "A nation in one man", "ar": "أمّةٌ في رجل"}, {"ref": "6:164", "q": "﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾", "en": "Each carries his own load", "ar": "كلٌّ يحمل وزره"}, {"ref": "2:141", "q": "﴿تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ﴾", "en": "The same words again, seven verses on", "ar": "الكلمات نفسها بعد سبع آيات"}], "v": 1, "p": 321, "pe": 321, "sid": 322},
  {"a": [135, 135], "h": "\"Be Jews or Christians and you will be guided\" — \"No: the religion of Ibrahim, upright\"", "hAr": "﴿كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ﴾ — ﴿بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ﴾", "said": "يعني أن اليهود قالوا: كونوا يهودا تهتدوا، وقال النصارى مثل ذلك، فأنزل الله تعالى على نبيه: ﴿قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ﴾ أي تتبع ملته المجمع على كونها هدى، وبين بقوله: ﴿وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾ أن كلتا الطائفتين قد أشركت، وأن إبراهيم كان حنيفا", "en": "The Jews said \"be Jews and you will be guided\", the Christians said the same. The answer: \"No — the religion of Ibrahim, upright\": follow the religion that every side agrees was guidance. Both claimed Ibrahim; neither could claim he was one of them.\n\"And he was not of those who associate partners with Allah\": a pointed reminder that both communities had fallen into association of partners, while Ibrahim was hanif — inclining away from every crooked way to the straight one. In the days before Islam, anyone on Ibrahim's religion was called hanif, and later anyone who was circumcised or made pilgrimage to the House, since these were part of his way.", "ar": "قالت اليهود: كونوا يهودًا تهتدوا، وقالت النصارى مثل ذلك، فأنزل الله: ﴿قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ﴾ — أي نتّبع ملّته المُجمَع على أنها هدى، وكلا الفريقين يدّعيه.\nوبيّن بقوله ﴿وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾ أن كلتا الطائفتين قد أشركت، وأن إبراهيم كان حنيفًا مائلًا عن كلّ طريقٍ معوجّةٍ إلى المستقيمة. وكان يُقال في الجاهليّة لمن كان على دين إبراهيم «حنيف»، ثم سُمّي من اختتن أو حجّ البيت حنيفًا لأن ذلك من سنّته.", "links": [{"ref": "3:67", "q": "﴿مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾", "en": "Neither side can claim him", "ar": "لا يدّعيه أحد الفريقين"}, {"ref": "3:65", "q": "﴿يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ﴾", "en": "The Torah and the Gospel came after him", "ar": "التوراة والإنجيل نزلا من بعده"}, {"ref": "9:30", "q": "﴿وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ﴾", "en": "Where each fell into association", "ar": "حيث وقع كلٌّ منهما في الشرك"}], "v": 1, "p": 322, "pe": 322, "sid": 323},
  {"a": [136, 136], "h": "\"We believe in Allah and what was sent to us… and to Ibrahim…\" — belief in detail, and belief in general", "hAr": "﴿قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا﴾ — إيمانٌ تفصيليّ وإيمانٌ إجماليّ", "said": "قيل: أما الابتداء بما أنزل إلينا، فلأنه أول بالإضافة إلينا، فالناس بعد مجيء محمد - صلى الله عليه وسلم -، مدعوون إلى الإيمان بما أنزل عليه أولا جملة وتفصيلا، ولا يجب الإيمان بما أنزل من قبل إلا على سبيل الجملة دون التفصيل، وأما المنزل إلى إسماعيل ومن ذكر معه، فهو المنزل على إبراهيم، إذ هم داخلون تحت شريعته، وذلك كقولك: ما أنزل على محمد - صلى الله عليه وسلم - والمسلمين ... فكأنه لما اختلف فيما أنزل عليهما، وادعى بعض أتباعهما عليهما ما لم ينزل إليهما بين تعالى أن ما أوتيا أي ما خصا به لا ما ادعي عليهما ... ثم قال: ﴿لَا نُفَرِّقُ بَيۡنَ أَحَدٖ﴾، أي لا يكون بمنزلة اليهود الذين آمنوا ببعض وكفروا ببعض", "en": "Four questions, and his answers:\n• Why start with \"what was sent down to us\", when it came last of all? Because it is first for us. Since Muhammad ﷺ came, people are called to believe in what was sent to him — in full and in detail; belief in what came before is required only in general, not in detail.\n• Why \"what was sent to Isma'il and Ishaq\", when no book was sent to them? Because what was sent to Ibrahim was sent to them — they lived under his law — as one says \"what was sent to Muhammad and the Muslims\".\n• Why \"what Musa and 'Isa were GIVEN\"? People disputed what had been revealed to them, and some of their followers attributed to them what was never revealed. So the verse affirms what they were truly given, what they were singled out with — not what was claimed for them — and what all the prophets, named and unnamed, were given from their Lord.\n• \"We make no distinction between any one of them\": we are not like those who believed in some messengers and rejected others. And \"any one of them\" rather than \"them\": not a single one is set apart from the rest.", "ar": "أربعة أسئلة وأجوبتها عند الراغب:\n• لماذا بدأ بـ﴿وَمَآ أُنزِلَ إِلَيۡنَا﴾ وهو آخر ما أُنزل؟ لأنه الأوّل بالإضافة إلينا: فالناس بعد مجيء محمد ﷺ مدعوّون إلى الإيمان بما أُنزل عليه جملةً وتفصيلًا، ولا يجب الإيمان بما أُنزل من قبلُ إلا على سبيل الجملة دون التفصيل.\n• لماذا ﴿وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ﴾ ولم يُنزَل على إسماعيل وإسحاق كتاب؟ لأن المنزَل على إبراهيم منزَلٌ إليهم، إذ هم داخلون تحت شريعته، كقولك: ما أُنزل على محمدٍ ﷺ والمسلمين.\n• لماذا ﴿وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ﴾؟ لمّا اختُلف فيما أُنزل عليهما، وادّعى بعض أتباعهما عليهما ما لم يُنزَل إليهما، بيّن أن الإيمان بما أوتيا حقًّا — ما خُصّا به — لا بما ادُّعي عليهما، وبما أوتي النبيّون جميعًا، المذكورون وغيرهم، من ربّهم.\n• ﴿لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ﴾: لسنا كمن آمن ببعضٍ وكفر ببعض. وقال «أحد» ولم يقل «بينهم» ليبيّن أنّا لا نفرّق بين واحدٍ وواحد، فلا يخرج واحدٌ من حكمهم.", "links": [{"ref": "3:84", "q": "﴿قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ﴾", "en": "The same declaration in Al 'Imran", "ar": "الإقرار نفسه في آل عمران"}, {"ref": "2:285", "q": "﴿كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ﴾", "en": "The believers' creed at the end of the surah", "ar": "عقيدة المؤمنين في خاتمة السورة"}, {"ref": "4:150", "q": "﴿وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ﴾", "en": "The distinction that is condemned", "ar": "التفريق المذموم"}], "v": 1, "p": 322, "pe": 323, "sid": 323},
  {"a": [137, 137], "h": "\"If they believe in the like of what you believe\" — not a \"like\" of Allah, but the same path", "hAr": "﴿فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾ — لا مثلَ لله، بل السبيل نفسه", "said": "إن قيل: كيف قال: ﴿فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾ ولم يقل بما آمنتم ... وذلك يقتضي إثبات مثل الله- عز وجل- ... قيل إن الباء ههنا ليس للتعدية كما هو في قولك (مررت بزيد)، و (آمنت بالله) وإنما هو للآلة، ومعناه أن تحروا الإيمان بالسبيل الذي تحريتم به، والإشارة بقوله: ﴿بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾ إلى السبيل المذكور في قوله: ﴿قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ﴾", "en": "A question that troubled some: \"in the LIKE of what you believe in\" — does that not suggest there is a \"like\" of Allah to believe in? (Ibn 'Abbas is even reported to have preferred reading it \"in what you believe in\".) Ar-Raghib answers from the grammar: the \"bi\" here is not the \"bi\" of \"I believe in Allah\" or \"I passed by Zayd\"; it is the \"bi\" of the means: \"if they seek faith by the same means by which you sought it\" — the path Allah describes: \"say: this is my path; I call to Allah with clear sight, I and those who follow me\".\nShiqaq is splitting away: \"splitting the staff\" is leaving the community; those who \"split from Allah\" put themselves on a side other than the side of His friends. \"Allah will suffice you against them\" was said to calm the believers.", "ar": "فإن قيل: كيف قال ﴿بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾ ولم يقل «بما آمنتم به»، وظاهره يقتضي إثبات مثلٍ لله؟ وقد رُوي عن ابن عباس أنه كره هذا اللفظ. قال الراغب: الباء هنا ليست للتعدية كما في «مررت بزيد» و«آمنت بالله»، وإنما هي للآلة: أي إن تحرّوا الإيمان بالسبيل الذي تحرّيتم به؛ والإشارة إلى السبيل المذكور في قوله: ﴿قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ﴾.\nو«الشقاق» المنازعة: «شقّ العصا» فارق الجماعة، و«شاقّوا الله» صاروا في شقٍّ غير شقّ أوليائه. و﴿فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾ تسكينٌ للمؤمنين.", "links": [{"ref": "12:108", "q": "﴿قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ﴾", "en": "\"The like of what you believe\" = this path", "ar": "«بمثل ما آمنتم به» = هذه السبيل"}, {"ref": "8:13", "q": "﴿ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ﴾", "en": "Shiqaq: taking the other side", "ar": "الشقاق: الانحياز إلى الشقّ الآخر"}, {"ref": "39:36", "q": "﴿أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ﴾", "en": "\"Allah will suffice you\"", "ar": "«فسيكفيكهم الله»"}], "v": 1, "p": 323, "pe": 323, "sid": 324},
  {"a": [137, 137], "h": "The path to Allah has three stages — the outward law, the purified self, the watched heart", "hAr": "سبيل الله ثلاث منازل — الأحكام الظاهرة، وتزكية النفس، ومراعاة الخواطر", "said": "وسبيل الله المتوصل به إليه ثلاث منازل على القول المجمل مرتب بعضها على بعض الأول: معرفة الأحكام الظاهرة والعمل بها، والثاني: معرفة علم الزهاد من عيوب النفس وقمع الشهوات وأخذ النفس به، والثالث: علم المعاملات، وهي معرفة الخواطر ومراعاتها، وذلك السبيل إليه، ولا سبيل إلى تحصيل الإيمان الحقيقي الذي وصف به المؤمنين في قوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾ إلا بها ... فبين تعالى أن من آمن سالكا هذا السبيل، فقد اهتدى", "en": "What is the path by which you believed? Ar-Raghib sums it up in three stages, each built on the one before:\n1. Knowing the outward rulings of the religion and acting on them.\n2. The knowledge of the ascetics: knowing the faults of one's own self, curbing its appetites, and holding it to that.\n3. The knowledge of inner dealings: knowing the thoughts that pass through the heart and keeping watch over them.\nThat is the path to Him — and there is no other way to the REAL faith Allah describes: \"the believers are only those whose hearts tremble when Allah is mentioned\". So whoever believes travelling this path is guided; whoever turns aside is in schism.\nHere he tells us plainly how he sees the religion: not rulings alone, not inner states alone, but rulings, then the self, then the heart — in that order.", "ar": "ما السبيل الذي آمنتم به؟ لخّصه الراغب في ثلاث منازل مرتّبٍ بعضها على بعض:\n١. معرفة الأحكام الظاهرة والعمل بها.\n٢. معرفة علم الزهّاد: عيوب النفس، وقمع الشهوات، وأخذ النفس بذلك.\n٣. علم المعاملات: معرفة الخواطر ومراعاتها.\nفذلك السبيل إليه، ولا سبيل إلى الإيمان الحقيقيّ الذي وصف به المؤمنين في قوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾ إلا بها. فمن آمن سالكًا هذه السبيل فقد اهتدى، ومن جمح عنها فهو في شقاق.\nوهنا يصرّح بنظرته إلى الدين: لا أحكامٌ وحدها، ولا أحوالٌ باطنة وحدها، بل الأحكام، ثم النفس، ثم القلب — على هذا الترتيب.", "links": [{"ref": "8:2", "q": "﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾", "en": "The real faith the path leads to", "ar": "الإيمان الحقيقيّ الذي تنتهي إليه السبيل"}, {"ref": "91:9-10", "q": "﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا ۝ وَقَدۡ خَابَ مَن دَسَّىٰهَا﴾", "en": "The second stage: purifying the self", "ar": "المنزلة الثانية: تزكية النفس"}, {"ref": "13:28", "q": "﴿أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ﴾", "en": "The third stage: the heart", "ar": "المنزلة الثالثة: القلب"}], "v": 1, "p": 323, "pe": 324, "sid": 324},
  {"a": [138, 138], "h": "\"The dye of Allah\" — the natural disposition He coloured us with", "hAr": "﴿صِبۡغَةَ ٱللَّهِ﴾ — الفطرة التي صبغنا بها", "said": "الصبغة إشارة من الله- عز وجل- إلى ما أوجده فينا من بداية العقول التي ميزنا بها من البهائم، رشحنا به لمعرفته ومعرفة حسن العدالة وطلب الحق وهو المشار إليه بالفطرة في قوله: ﴿فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ﴾ ... ولما كانت اليهود والنصارى إذا لقنوا أولادهم اليهودية والنصرانية يقولون قد صبغناه بين تعالى أن الإيمان بمثل ما آمنتم به هو صبغة الله وفطرته التي ركزها في الخلق، ولا أحد أحسن صبغة منه ... وقد قيل: صبغة الله على مراتب أولها ما ركب فينا من الهداية وهي الفطرة والثانية: الهداية بالتوفيق، والثالثة: الهداية ببعثة الرسل، والرابعة: الهداية في الترقي توليه إلى الدرجة العليا والسعادة القصوى", "en": "\"The dye of Allah\" points to what Allah placed in us from the start: the first beginnings of reason, which set us apart from the animals and prepared us to know Him, to know the beauty of justice, and to seek the truth. It is the \"natural disposition (fitrah)\" of \"the fitrah of Allah upon which He created people — no change to Allah's creation\", and what the Prophet ﷺ meant by \"every child is born upon the fitrah\".\nWhy \"dye\"? Because the faculties a person is made with, taken as a beginning, are like a dye that adorns what it colours. And the Jews and Christians, when they taught their children their religion, used to say \"we have dyed him\". Allah answers: the faith you believers hold is Allah's own dye, the fitrah He planted in His creation — and who dyes better than Allah? \"And we worship Him\": a hint at them — we associate no one with Him, as you do. (Religion, the law, circumcision — the commentators' answers all point to one aim.)\nAllah's dye comes in stages: the guidance built into us, the fitrah; guidance by His enabling (tawfiq); guidance by sending messengers; and guidance in rising — His taking charge of a person up to the highest rank and the utmost happiness.", "ar": "«الصبغة» إشارةٌ إلى ما أوجده الله فينا من بدايات العقول التي ميّزنا بها من البهائم، وهيّأنا بها لمعرفته ومعرفة حسن العدالة وطلب الحقّ؛ وهي «الفطرة» في قوله: ﴿فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ﴾، والمعنيّة بقوله ﷺ: «كلّ مولودٍ يولد على الفطرة».\nوسُمّيت صبغةً لأن قوى الإنسان التي رُكّب عليها — إذا اعتُبرت بدايةً — تجري مجرى الصبغ الذي يزيّن المصبوغ. وكانت اليهود والنصارى إذا لقّنوا أولادهم دينهم قالوا: قد صبغناه؛ فبيّن تعالى أن الإيمان الذي عليه المؤمنون هو صبغة الله وفطرته التي ركزها في الخلق، ولا أحد أحسن صبغةً منه. و﴿وَنَحۡنُ لَهُۥ عَٰبِدُونَ﴾ تعريضٌ بهم: لا نشرك به كشرككم. (وأقوالهم: الدين، الشريعة، الختان — تشير إلى مغزًى واحد.)\nوصبغة الله مراتب: الهداية المركّبة فينا — وهي الفطرة —، ثم الهداية بالتوفيق، ثم الهداية ببعثة الرسل، ثم الهداية في الترقّي بتولّيه إلى الدرجة العليا والسعادة القصوى.", "links": [{"ref": "30:30", "q": "﴿فَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ﴾", "en": "The dye = the fitrah", "ar": "الصبغة = الفطرة"}, {"ref": "20:50", "q": "﴿ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ﴾", "en": "The first stage: guidance built into creation", "ar": "المرتبة الأولى: هدايةٌ مركّبةٌ في الخلق"}, {"ref": "47:17", "q": "﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ﴾", "en": "The last stage: guidance that keeps rising", "ar": "المرتبة الأخيرة: هدايةٌ تترقّى"}], "v": 1, "p": 324, "pe": 325, "sid": 325},
  {"a": [139, 139], "h": "\"Do you argue with us about Allah?\" — the test of sincerity is the five pillars of belief", "hAr": "﴿أَتُحَآجُّونَنَا فِي ٱللَّهِ﴾ — ميزان الإخلاص أصول الاعتقاد الخمسة", "said": "ولما كانت الشرائع مبنية بالقول المجمل على ثلاثة أشياء ... الإقرار بالباري- عز وجل-، والعمل له والإخلاص في ذلك قال .. قل لهم إنا قد تشاركنا في الإقرار بالله- عز وجل- وفى العمل له ونحن قد حصل لنا الإخلاص [في ذلك] من دونكم ... قيل قد أحالهم على التأمل، وذلك ظاهر بالاستقراء والتدبر، فإن الأصول الاعتقادية هي ما ذكر الله- عز وجل-، [في قوله] ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾ وإذا تأمل حالة الإقرار بالله تعالي فقد أخلص المسلمون فيها [مما] يدعيه اليهود من التشبيه والنصارى من التثليث", "en": "Every revealed religion rests, in brief, on three things: acknowledging the Creator, acting for Him, and sincerity in both. So the Prophet ﷺ is told to say: we share with you the acknowledging and the acting — \"He is our Lord and your Lord; we have our deeds and you have yours\" — but sincerity is ours, not yours: \"and we are sincere to Him\".\nIs that not just a claim? No — ar-Raghib says the verse leaves them to examine it, and examination makes it plain. The foundations of belief are the five Allah names: \"Allah, His angels, His books, His messengers and the Last Day\". Take each: in believing in Allah, the Muslims kept Him pure of what some attributed to Him — likening Him to creatures, or making Him one of three; in the angels, of calling Jibril an enemy; in the messengers, of denying that Ibrahim was a prophet, or of what was claimed about 'Isa; in the books, of rejecting part of the Torah and the Gospel; and in the Last Day, of \"the Fire will touch us only for a few days\", or of a resurrection of souls without bodies. Wherever you look, sincerity — purity of belief — is on this side.", "ar": "الشرائع مبنيّةٌ — بالقول المجمل — على ثلاثة أشياء: الإقرار بالبارئ، والعمل له، والإخلاص في ذلك. فقال: قل لهم: قد تشاركنا في الإقرار بالله والعمل له — ﴿وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ﴾ —، ونحن قد حصل لنا الإخلاص دونكم: ﴿وَنَحۡنُ لَهُۥ مُخۡلِصُونَ﴾.\nفإن قيل: أليس هذا مجرّد دعوى؟ قيل: أحالهم على التأمّل، وهو ظاهرٌ بالاستقراء والتدبّر: فأصول الاعتقاد ما ذكره الله في قوله: ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾؛ فإذا تُؤمّل الإقرار بالله فقد أخلص فيه المسلمون ممّا يدّعيه اليهود من التشبيه والنصارى من التثليث؛ وفي الملائكة ممّا ادّعوه على جبريل أنه عدوّهم؛ وفي الرسل ممّا زعموه في إبراهيم أنه لم يكن نبيًّا، وما ادّعته النصارى في عيسى؛ وفي الكتب من إنكارهم بعض ما في التوراة والإنجيل؛ وفي اليوم الآخر من قولهم ﴿لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ﴾، ومن زعم أن الثواب والعقاب للأرواح وحدها. فقول المسلمين ﴿وَنَحۡنُ لَهُۥ مُخۡلِصُونَ﴾ ظاهر.", "links": [{"ref": "4:136", "q": "﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا﴾", "en": "The five foundations of belief", "ar": "أصول الاعتقاد الخمسة"}, {"ref": "39:3", "q": "﴿أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ﴾", "en": "Sincerity: religion kept pure", "ar": "الإخلاص: الدين الخالص"}, {"ref": "39:14", "q": "﴿قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصٗا لَّهُۥ دِينِي﴾", "en": "\"We are sincere to Him\"", "ar": "«ونحن له مخلصون»"}], "v": 1, "p": 325, "pe": 325, "sid": 326},
  {"a": [140, 140], "h": "\"Were Ibrahim and his sons Jews or Christians?\" — the earlier cannot follow the later", "hAr": "﴿أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ﴾ … ﴿كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ﴾ — المتقدّم لا يقتدي بالمتأخّر", "said": "قوله: ﴿أَمۡ تَقُولُونَ﴾ معطوف على قوله (أتحاجوننا) - أم تدعون أن الأنبياء كانوا على دينكم تنبيها أنه من المحال أن يكون المتقدم مقتديا بالمتأخر ومستنا بسنته، ومن قرأ بالياء فوجه العدول فيه من الخطاب إلى الإخبار استجهالا لهم بما كان منهم من هذه الدعوى ... واحتج عليهم بمقدمتين فقال: أنتم أعلم أم الله أي قد بينت أن الله أعلم منكم، وبينت أنه ليس بغافل عما تعملون وقد كتمتم الشهادة عنها، ومن كتم من الله شهادة عنده مع كون الله بهذا الوصف فهو أظلم الخلائق، فهذا تبكيت لهم في كتمانهم أحوال النبي- عليه السلام- وسائر الأنبياء", "en": "\"Or do you claim that the prophets were on your religion?\" — a pointer to the impossible: that those who came first could be following those who came after them, and living by their customs. (Read \"or do THEY claim\", the verse turns away from them to speak about them — as a scholar turns from someone who has said something shamefully ignorant and addresses another.)\nThen two premises settle it: \"Do you know better, or Allah?\" — Allah knows better than you; and \"Allah is not unaware of what you do\" — while you have hidden the testimony you hold. Whoever hides a testimony he holds from Allah, when Allah is thus, is the most unjust of all creatures. It is a rebuke for hiding what their books said about the Prophet ﷺ and about the other prophets.", "ar": "﴿أَمۡ تَقُولُونَ﴾ معطوفٌ على ﴿أَتُحَآجُّونَنَا﴾: أم تدّعون أن الأنبياء كانوا على دينكم؟ تنبيهًا على أنه من المحال أن يكون المتقدّم مقتديًا بالمتأخّر مستنًّا بسنّته. ومن قرأ بالياء فوجه العدول من الخطاب إلى الإخبار استجهالهم بهذه الدعوى، كما يُعرض العالم عمّن ارتكب جهالةً شنيعةً إلى غيره.\nواحتجّ عليهم بمقدّمتين: ﴿قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ﴾ — قد بيّنتُ أن الله أعلم منكم —، و﴿وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾ — وقد كتمتم الشهادة؛ ومن كتم شهادةً عنده من الله، والله بهذا الوصف، فهو أظلم الخلائق. فهذا تبكيتٌ لهم في كتمانهم أحوال النبي ﷺ وسائر الأنبياء.", "links": [{"ref": "3:65", "q": "﴿يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ﴾", "en": "The Torah and the Gospel came after him", "ar": "التوراة والإنجيل نزلا من بعده"}, {"ref": "2:283", "q": "﴿وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ﴾", "en": "Hiding a testimony", "ar": "كتمان الشهادة"}, {"ref": "2:159", "q": "﴿إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ﴾", "en": "Hiding what Allah revealed", "ar": "كتمان ما أنزل الله"}], "v": 1, "p": 326, "pe": 326, "sid": 327},
  {"a": [141, 141], "h": "Why \"That was a nation which has passed\" is said twice — pride in ancestors dies hard", "hAr": "لماذا تكرّرت ﴿تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ﴾ — الافتخار بالآباء عادةٌ مستحكمة", "said": "أعيدت هذه الآية من أجل أن العادة مستحكمة في الناس صالحهم وطالحهم أن يفتخروا بآبائهم ويقتدوا بهم في متحرياتهم سيما في أمور دينهم، ولهذا حكى عن الكفار قولهم: ﴿إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ﴾، فأكد الله تعالى القول في إنزالهم عن هذه الطريقة ... تنبيها على نحو ما قال: ﴿وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ﴾، وقوله: ﴿لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ﴾، وقوله: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾", "en": "The verse returns word for word from 2:134 because the habit is so deeply rooted in people — the good among them and the bad — of taking pride in their forefathers and following them in what they aim at, above all in religion. The disbelievers said it outright: \"we found our fathers on a way, and we are following in their footsteps\". So Allah pressed the point again to bring them down from that path.\nThe first time it came after Ibrahim's and Ya'qub's charge to their sons: whatever your forefathers were, their reward is not yours, nor their punishment. The second time it comes after their claim that those fathers were Jews or Christians. Each person carries his own record: \"We have fastened every person's fate to his neck\", \"to it what it earned, and against it what it incurred\", \"no bearer of burdens bears another's burden\". As the Arabs say, \"every sheep is hung by its own legs\".", "ar": "أُعيدت الآية (بعد ١٣٤) لأن العادة مستحكمةٌ في الناس — صالحهم وطالحهم — أن يفتخروا بآبائهم ويقتدوا بهم في متحرّياتهم، لا سيّما في أمور دينهم؛ ولهذا حكى عن الكفّار قولهم: ﴿إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ﴾، فأكّد الله القول في إنزالهم عن هذه الطريقة.\nذُكرت أوّلًا بعد وصيّة إبراهيم ويعقوب بنيهما: فليس لكم ثواب فعل آبائكم ولا عليكم عقابه؛ وثانيًا بعد ادّعائهم اليهوديّة والنصرانيّة لآبائهم، تأكيدًا عليهم، على نحو قوله: ﴿وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ﴾، و﴿لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ﴾، و﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾. وكما جرى في أمثالهم: «كلّ شاةٍ تُناط برِجلَيها».", "links": [{"ref": "43:23", "q": "﴿إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ﴾", "en": "The habit the repetition is aimed at", "ar": "العادة التي يُراد بالتكرار نزعها"}, {"ref": "17:13", "q": "﴿وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ﴾", "en": "Each carries his own record", "ar": "كلٌّ يحمل عمله في عنقه"}, {"ref": "2:134", "q": "﴿تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ﴾", "en": "The first time it was said", "ar": "المرّة الأولى"}], "v": 1, "p": 327, "pe": 327, "sid": 328},
  {"a": [142, 142], "h": "\"The foolish will say: what turned them from their qibla?\" — all places are equal before Allah", "hAr": "﴿سَيَقُولُ ٱلسُّفَهَآءُ﴾ … ﴿مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ﴾ — الأمكنة متساويةٌ عند الله", "said": "السفيه كل معتقد باطلا يسرع إلى إظهار معتقده، ولا يكون له ثبات ... وهؤلاء السفهاء المنكرون لتغيير القبلة اليهود على ما روي عن ابن عباس، ومشركو العرب عن الحسن، والمنافقون عن السدي، ولا تنافي بين أقوالهم، فكل قد عابوا وكل سفهاء ... فأنزل الله تعالى ذلك تبيينا أن الأمكنة متساوية عند الله، فله المشرق والمغرب، وهو الهادي إلى الطريق المستقيم فأي وجه يتوجه إليه، فهو تعالى موجود كما قال ﴿فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾", "en": "A safih, \"fool\", is anyone who holds a false belief, is quick to air it, and has no steadiness. Qiblah first meant the posture of facing, then the place one faces in prayer.\nWho were \"the foolish\"? The Jews (Ibn 'Abbas), the Arab idolaters (al-Hasan), the hypocrites (as-Suddi) — no contradiction: all of them found fault, and all of them were foolish. Some said \"Muhammad holds to no religion for long\"; some said \"he has gone back to his people's qibla, and will go back to their religion\"; some Jews came and said \"go back to our qibla and we will follow you\".\nThe answer shows that all places are equal before Allah: to Him belong the east and the west, and He guides to the straight path. Whatever direction one faces, He is there — \"wherever you turn, there is the Face of Allah\" — by turning to Him and following His command, not by places and directions.", "ar": "«السفيه» كلّ معتقدٍ باطلًا يُسرع إلى إظهار معتقده ولا يكون له ثبات. و«القبلة» في الأصل الحال التي عليها المستقبِل، ثم صارت للمكان المتوجَّه نحوه في الصلاة.\nو«السفهاء» المنكرون لتحويل القبلة: اليهود (ابن عباس)، أو مشركو العرب (الحسن)، أو المنافقون (السدّي) — ولا تنافي، فكلٌّ عابوا وكلٌّ سفهاء. قال بعضهم: لا يثبت محمدٌ على دين؛ وقال بعضهم: رجع إلى قبلة قومه وسيرجع إلى دينهم؛ وأتاه قومٌ من اليهود فقالوا: ارجع إلى قبلتنا نتّبعك.\nفأنزل الله ذلك تبيينًا أن الأمكنة متساويةٌ عنده: فله المشرق والمغرب، وهو الهادي إلى الصراط المستقيم، فأيّ وجهٍ توجّه إليه العبد فهو تعالى موجود، كما قال: ﴿فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾ — باعتباره والارتسام لأوامره، لا بالأمكنة والجهات.", "links": [{"ref": "2:115", "q": "﴿وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾", "en": "The same words, prepared twenty-seven verses earlier", "ar": "الكلمات نفسها مهيّأةً قبل سبعٍ وعشرين آية"}, {"ref": "43:84", "q": "﴿وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٞ وَفِي ٱلۡأَرۡضِ إِلَٰهٞۚ﴾", "en": "Not by places and directions", "ar": "لا بالأمكنة والجهات"}], "v": 1, "p": 327, "pe": 328, "sid": 328},
  {"a": [143, 143], "h": "\"A middle nation\" — a law between burdens and neglect", "hAr": "﴿أُمَّةٗ وَسَطٗا﴾ — شريعةٌ بين الآصار والإهمال", "said": "الوسط في الأصل اسم للمكان الذي يستوي إليه المساحة من الجوانب في المدورة، ومن الطرفين في المطول كالنقطة من الدائرة ولسان الميزان من العمود، ويجعل عبارة عن العدل ... وشبه به كل ما وقع بين طرفين إفراط وتفريط كالجود بين السرف والبخل والشجاعة بين التهور والجبن، ثم جعل عبارة عن المختار من كل شيء ... قيل: قد خصهم بكل ذلك، والظاهر من ذلك هي الشريعة التي إذا اعتبرت بسائر الشرائع وجد لها حد الاعتدال، وهو أن بني إسرائيل لما عتوا كما حكى الله عنهم في غير موضع شدد عليهم أشياء صارت عليهم إصرا وأغلالا ... ثم خفف عنهم على لسان عيسى بعض التخفيف ... فصارت شريعته متوسطة بين الإفراط الذي هو الإصر والأغلال وبين التفريط الذي هو الإضاعة والإهمال، وعلى ذلك قال ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾", "en": "Wasat is first the point equally distant from every side — the centre of a circle, the pointer of a balance — and so it came to mean justice. It is used for everything that lies between two extremes, excess and falling short: generosity between extravagance and miserliness, courage between recklessness and cowardice; and then for the best of anything.\nIn what way is this nation \"middle\" — in its making, its knowledge, its law? In all of these, ar-Raghib says, but most visibly in its law, which, measured against the other laws, has the balance. When the Children of Israel rebelled, things were made hard for them until they became burdens and shackles — \"We forbade them the fat of cattle and sheep…\" — which is why we are taught to pray \"do not lay on us a burden like the one You laid on those before us\". Then some of it was lightened through 'Isa (\"to make lawful for you some of what was forbidden to you\"), and it was completed with Muhammad ﷺ, who \"makes the good things lawful for them… and removes their burdens and the shackles that were on them\"; \"Allah does not want to place hardship on you\".\nSo his law stands in the middle — between the excess of burdens and shackles, and the falling short of carelessness and neglect. That is why this is \"the best nation\", and why its message is called \"a word of equity\" — just, by the agreement of every sound mind: \"O People of the Book, come to a word of equity between us and you\".", "ar": "«الوسط» في الأصل اسم المكان الذي تستوي إليه المسافة من الجوانب — كالنقطة من الدائرة، ولسان الميزان —، ثم جُعل عبارةً عن العدل، وشُبّه به كلّ ما وقع بين طرفي إفراطٍ وتفريط: كالجود بين السرف والبخل، والشجاعة بين التهوّر والجبن؛ ثم عن المختار من كلّ شيء.\nوبمَ جعلهم وسطًا؟ بالخَلق أم بالعلم أم بالشرع؟ قال: خصّهم بكلّ ذلك، والظاهر منه الشريعة، فإذا اعتُبرت بسائر الشرائع وُجد لها حدّ الاعتدال: فبنو إسرائيل لمّا عتَوا شُدّد عليهم في أشياء صارت عليهم إصرًا وأغلالًا — ﴿وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ﴾ —، ولذلك أُمرنا أن ندعو: ﴿وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ﴾؛ ثم خُفّف عنهم على لسان عيسى بعض التخفيف — ﴿وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ﴾ —، وتمّم ذلك بمحمدٍ ﷺ: ﴿وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ﴾، و﴿مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ﴾.\nفصارت شريعته متوسّطةً بين الإفراط — الإصر والأغلال — والتفريط — الإضاعة والإهمال —؛ وعلى ذلك قال: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾. ولكونها وسطًا سُمّي مقتضاها «كلمة سواء» أي عدلًا باتّفاق العقول: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ﴾.", "links": [{"ref": "7:157", "q": "﴿وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ﴾", "en": "The burdens lifted by this law", "ar": "الآصار التي رفعتها هذه الشريعة"}, {"ref": "2:286", "q": "﴿وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ﴾", "en": "The prayer we are taught", "ar": "الدعاء الذي عُلّمناه"}, {"ref": "3:110", "q": "﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾", "en": "Middle, and therefore best", "ar": "وسطٌ فخير"}, {"ref": "3:64", "q": "﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ﴾", "en": "\"A word of equity\"", "ar": "«كلمة سواء»"}], "v": 1, "p": 328, "pe": 330, "sid": 329},
  {"a": [143, 143], "h": "\"Witnesses over people\" — who may be one: justice with oneself, with people, with Allah", "hAr": "﴿لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ﴾ — من يكون شاهدًا: عدلٌ مع النفس ومع الناس ومع الله", "said": "إن قيل: هل ذلك للأمة كلهم أم للبعض دون البعض؟ قيل: الخطاب لأصحاب النبي - صلى الله عليه وسلم - خاصة على وجه، وهو خطاب للكافة عامة على وجه، وذلك أن أصحابه في الحقيقة صاروا موجودين خير الناس، وسائر أمته ممكنون أن يصيروا أخيارا ... قيل: كلهم ممكنون من أن يكونوا شهداء وذلك بشريطة أن يزكوا أنفسهم بالعلم والعمل الصالح، فمن لم يزك نفسه لم يكن شاهدا مقبولا، ولذلك قال تعالى: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾، وعلى هذا قال: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ﴾، فالقيام بالقسط مراعاة العدالة، وهي بالقول المجمل ثلاث: عدالة بين الإنسان ونفسه، وعدالة بينه وبين الناس، وعدالة بينه وبين الله- عز وجل-، فمن رعى ذلك فقد صار عدلا شاهدا لله- عز وجل-", "en": "Is this said to the whole nation or to some of it? To the Companions in one sense — they actually became the best of people — and to everyone in another: the rest of the nation are ABLE to become the best, by accepting the grace Allah has opened to them through their own reason and their Prophet's words, and rising in it step by step.\nA witness is one who knows a thing and reports it, making its ruling clear; the greatest witness is one whose testimony stands on proof. Allah gave people reason and the ability to tell good from evil, completed it by sending prophets, and gave this nation the most complete Book — \"We have neglected nothing in the Book\". What the Prophet ﷺ taught and explained is a proof against anyone who would say \"no bringer of good news and no warner came to us\"; and his nation, who know it, are made witnesses over the rest of people.\nBut not automatically. Every one of them can be a witness — on condition that he purifies himself by knowledge and righteous action; one who has not purified himself is not an acceptable witness (\"successful is he who purifies it\"). \"Be upholders of justice, witnesses for Allah, even against yourselves\": justice is of three kinds — between a person and himself, between him and other people, and between him and Allah. Whoever keeps all three has become a just witness for Allah.", "ar": "هل ذلك للأمّة كلّها أم لبعضها؟ الخطاب للصحابة خاصّةً على وجه — فقد صاروا في الحقيقة خير الناس —، وللكافّة عامّةً على وجه: فسائر الأمّة ممكَّنون أن يصيروا أخيارًا بقبولهم الفيض الذي أباحه الله لهم بعقولهم ولسان نبيّهم، وتدرّجهم إلى بلوغ أقاصيه.\nو«الشاهد» العالم بالشيء المخبر عنه مبيّنًا حكمه، وأعظم الشهود من ثبتت شهادته بحجّة. خصّ الله الإنسان بالعقل والتمييز بين الخير والشرّ، وكمّله ببعثة الأنبياء، وخصّ هذه الأمّة بأتمّ كتاب — ﴿مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ﴾، ﴿وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ﴾ —، فما أفادناه ﷺ وبيّنه صار حجّةً وشاهدًا أن نقول ﴿مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ﴾، وجعل أمّته العارفة به شهودًا على سائر الناس.\nوكلّهم ممكَّنون أن يكونوا شهداء، بشرط أن يزكّوا أنفسهم بالعلم والعمل الصالح؛ فمن لم يزكِّ نفسه لم يكن شاهدًا مقبولًا: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾. وعلى هذا ﴿كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ﴾: فالقيام بالقسط مراعاة العدالة، وهي ثلاث: عدالةٌ بين الإنسان ونفسه، وعدالةٌ بينه وبين الناس، وعدالةٌ بينه وبين الله؛ فمن رعى ذلك صار عدلًا شاهدًا لله.", "links": [{"ref": "4:135", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ﴾", "en": "Witnesses for Allah — even against oneself", "ar": "شهداء لله ولو على أنفسهم"}, {"ref": "91:9", "q": "﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾", "en": "The condition: a purified self", "ar": "الشرط: نفسٌ مزكّاة"}, {"ref": "16:89", "q": "﴿وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ﴾", "en": "The complete Book they witness by", "ar": "الكتاب التامّ الذي يشهدون به"}, {"ref": "5:19", "q": "﴿أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ﴾", "en": "The excuse the witness removes", "ar": "العذر الذي تقطعه الشهادة"}], "v": 1, "p": 330, "pe": 331, "sid": 331},
  {"a": [143, 143], "h": "\"Only so that We might know…\" — how can Allah come to know what He always knew?", "hAr": "﴿إِلَّا لِنَعۡلَمَ﴾ — كيف «يعلم» الله ما لم يزل يعلمه؟", "said": "إن قيل: ما وجه قوله: ﴿إِلَّا لِنَعۡلَمَ﴾، وذلك يقتضي استفادة علم وقد علم أن الله تعالى لم يزل عالما بما كان، وبما يكون؟ قيل إن ذلك من الألفاظ التي لولا السمع لما تجاسرنا على إطلاقها عليه تعالى، ومجاز ذلك على أوجه .. الأول: أن اللام في مثل ذلك تقتضي شيئين: حدوث الفعل في نفسه، وحدوث العلم به، ولما كان علم الله لم يزل ولا يزال صار اللام فيه مقتضيا حدوث الفعل لا حدوث العلم. والثاني: أن العلم يتعلق بالشيء على [ما] هو به، والله تعالى علمهم قبل أن يتبعوه غير تابعين، وبعد أن تبعوه علمهم تابعين، وهذا الجواب كالأول في الحقيقة، لأن التغيير داخل في المعلوم لا في العلم", "en": "\"We did not appoint the qibla you were on except so that We might know who follows the Messenger\" — but Allah has always known what was and what will be. Ar-Raghib: we would never dare say such a thing of Allah if revelation had not said it; it has several senses:\n1. \"So that\" here brings two things: the deed happening, and knowledge of it happening. Since Allah's knowledge has no beginning and no end, it brings only the deed.\n2. Knowledge fits a thing as it is: before they followed, Allah knew them as not yet following; after, He knew them as followers. The change is in what is known, not in the knowing.\n3. \"So that Our party might know\": He ascribes to Himself what His friends do — as He says \"Allah takes the souls at their death\", and also \"the angel of death… takes you\"; and \"He taught you what you did not know\", though He taught through His angels.\n4. \"So that We might repay\": as one says \"I shall know your good service\", meaning I will reward it.\n5. A wise teacher says \"until we know…\" when he means to make his student know, placing himself beside the learner out of kindness.", "ar": "﴿وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ﴾: والله لم يزل عالمًا بما كان وبما يكون. قال الراغب: هذه من الألفاظ التي لولا السمع لما تجاسرنا على إطلاقها عليه تعالى، ولها أوجه:\n١. اللام في مثله تقتضي شيئين: حدوث الفعل وحدوث العلم به؛ ولمّا كان علم الله لم يزل ولا يزال، اقتضت حدوث الفعل لا حدوث العلم.\n٢. العلم يتعلّق بالشيء على ما هو به: علمهم قبل أن يتّبعوا غير تابعين، وبعد أن اتّبعوا تابعين؛ فالتغيّر في المعلوم لا في العلم.\n٣. «لنعلم»: ليعلم حزبنا، فنسب فعل أوليائه إلى نفسه، كقوله ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾ مع قوله ﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ﴾، وقوله ﴿وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ﴾ وإنما علّمه بملائكته.\n٤. «لنعلم»: لنجازي، كقولك «سأعلم حسن بلائك» أي سأجازيك عليه.\n٥. من عادة الحكيم إذا أفاد غيره علمًا أن يقول «حتى نعلم كذا»، يريد إعلام المخاطب، فيُحلّ نفسه محلّ المشارك للمتعلّم تلطّفًا.", "links": [{"ref": "39:42", "q": "﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾", "en": "His act — and His angels' act", "ar": "فعله وفعل ملائكته"}, {"ref": "32:11", "q": "﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ﴾", "en": "The same act, ascribed to the angel", "ar": "الفعل نفسه منسوبًا إلى الملَك"}, {"ref": "4:113", "q": "﴿وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ﴾", "en": "Taught by Him, through the angels", "ar": "علّمه، والتعليم بواسطة الملائكة"}], "v": 1, "p": 332, "pe": 332, "sid": 333},
  {"a": [143, 143], "h": "\"Turning back on one's heels\" — falling from a rank one has reached", "hAr": "﴿مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ﴾ — الرجوع عن مرتبةٍ بلغها الإنسان", "said": "قيل: يتصور ذلك على وجهين: أحدهما: اعتبار لحال الإنسان ومعارفه، وهو أن الإنسان شرع في الفضيلة واكتساب المعرفة درجة درجة إلى حين الكمال، فإن حكمه في بطن أمه حكم النبات، ثم يصير في حكم الحيوان، ثم يصير بعد الولادة في حيز الإنسان باكتساب المعارف أولا فأول، ثم لا يزال يترقى بالعلم والعمل حتى ربما يصير قريبا من الملائكة علما وفضلا وعملا، ومتى أخل بمرتبته، وصل إليها، فرجع عنها فقد انقلب على عقبيه، والوجه الثاني: أن يعتبر الأديان وفضائلها، وذلك أن الله تعالى أنشأ الأديان، فما زال يتممها شيئا فشيئا إلى أن كملها بالنبي - صلى الله عليه وسلم - كما قال تعالى: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾ ... فمن أنعم عليه بأن أوجده بعد بعثته (عليه السلام) فرغب عن شريعته مائلا إلى غيرها من الشرائع المنسوخة فقد انقلب على عقبيه ... وعلم أنه تعالى يأمر عباده بما هو أصلح لهم كأهل \" قباء \" الذين لما أتاهم الخبر بنسخ القبلة، وكانوا في الصلاة حولوا وجوههم نحو الكعبة من غير أن يستبينوا", "en": "What does \"turning back on one's heels\" really mean? Two pictures:\n• The person. A human rises in virtue and knowledge step by step toward completeness: in the womb he is like a plant, then like an animal, and after birth he enters the human realm by acquiring knowledge little by little; and he can keep rising by knowledge and action until he comes close to the angels in knowledge, virtue and deeds. Whenever he lets go of a rank he has reached and slips back from it, he has turned back on his heels.\n• The religions. Allah brought the religions into being and kept completing them bit by bit until He perfected them with the Prophet ﷺ — \"today I have perfected your religion for you\"; the Prophet ﷺ likened himself to the last brick that completes a house. Whoever is blessed to live after his coming and turns from his law toward a law that has been superseded has turned back on his heels.\n\"It was hard indeed, except for those Allah guided\": leaving a familiar qibla is hard on human nature, which clings to what it is used to — above all in religion. It is not heavy for those who know Allah's wisdom and that He commands what is best for His servants — like the people of Quba', who heard in the middle of their prayer that the qibla had changed and turned toward the Ka'bah on the spot, without waiting to make sure.", "ar": "كيف يُتصوّر الانقلاب على العقبين؟ على وجهين:\n• باعتبار حال الإنسان ومعارفه: فالإنسان يشرع في الفضيلة واكتساب المعرفة درجةً درجةً إلى حين الكمال: حكمه في بطن أمّه حكم النبات، ثم يصير في حكم الحيوان، ثم يصير بعد الولادة في حيّز الإنسان باكتساب المعارف أوّلًا فأوّلًا، ثم لا يزال يترقّى بالعلم والعمل حتى ربما صار قريبًا من الملائكة علمًا وفضلًا وعملًا؛ ومتى أخلّ بمرتبةٍ وصل إليها فرجع عنها فقد انقلب على عقبيه.\n• باعتبار الأديان: أنشأ الله الأديان، فما زال يتمّمها شيئًا فشيئًا حتى أكملها بالنبي ﷺ: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾، وقد مثّل ﷺ نفسه باللبنة التي تمّ بها البناء. فمن أنعم الله عليه بأن أوجده بعد بعثته فرغب عن شريعته مائلًا إلى الشرائع المنسوخة فقد انقلب على عقبيه.\nو﴿وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ﴾: الانتقال عن المألوف من القبلة مستصعبٌ على الطبع، والإنسان ألوفٌ لما تعوّده، لا سيّما في الشريعة؛ ولا يثقل على من هداه الله وعرف حكمته وأنه يأمر عباده بما هو أصلح لهم — كأهل قُباء، أتاهم خبر نسخ القبلة وهم في الصلاة فحوّلوا وجوههم نحو الكعبة من غير أن يستبينوا.", "links": [{"ref": "5:3", "q": "﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي﴾", "en": "The religions completed", "ar": "اكتمال الأديان"}, {"ref": "3:144", "q": "﴿وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ﴾", "en": "Turning back harms only oneself", "ar": "الانقلاب لا يضرّ إلا صاحبه"}, {"ref": "95:4-5", "q": "﴿لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ ۝ ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ﴾", "en": "Rising and falling in rank", "ar": "الترقّي والانحطاط"}], "v": 1, "p": 333, "pe": 333, "sid": 334},
  {"a": [143, 143], "h": "\"Allah would never let your faith go to waste\" — the prayers toward Jerusalem were not lost", "hAr": "﴿وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ﴾ — لم تضع الصلاة إلى بيت المقدس", "said": "وقوله: ﴿وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ﴾ هو تسكين لمن صلى إلى بيت المقدس، من المسلمين ومن أهل الكتاب قبل النسخ، وبين أنهم يثابون على ذلك، فقد روي أن قوما قالوا: كيف بمن مات من إخواننا وقد صلوا إلى بيت القدس؟ فأنزل الله تعالى، ذلك ... قيل: عدل إلى لفظ الإيمان الذي هو عام في الصلاة وغيرها ليفيدهم أنه لم يضع لهم شيء مما عملوا به ثم نسخ عنهم ... فإن رأفته بالناس وإضاعة إحسانهم متنافيان لا يجتمعان", "en": "This calms everyone who had prayed toward Jerusalem — Muslims, and People of the Book before their law was superseded — and tells them they will be rewarded for it. It is reported that people asked, \"what of our brothers who died having prayed toward Jerusalem?\", and this was revealed.\nWhy \"your faith\" and not \"your prayers\"? The wider word tells them that nothing at all they had done — and which was later superseded — has been lost. Why \"your\" and not \"their\"? So that it covers the living and the dead together, the ones addressed standing for all. And \"Allah is Kind and Merciful to people\": His kindness and letting their good deeds go to waste cannot exist together.", "ar": "﴿وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ﴾ تسكينٌ لمن صلّى إلى بيت المقدس — من المسلمين، ومن أهل الكتاب قبل النسخ —، وبيانٌ أنهم يُثابون على ذلك. ورُوي أن قومًا قالوا: كيف بمن مات من إخواننا وقد صلّوا إلى بيت المقدس؟ فأنزل الله ذلك.\nولماذا «إيمانكم» لا «صلاتكم»؟ عدل إلى لفظ الإيمان العامّ في الصلاة وغيرها ليفيدهم أنه لم يضع لهم شيءٌ ممّا عملوا به ثم نُسخ عنهم. ولماذا «إيمانكم» لا «إيمانهم»؟ ليتناول الماضين والباقين، تغليبًا للمخاطَب على الغائب. ثم ﴿إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ﴾: فرأفته بالناس وإضاعة إحسانهم متنافيان لا يجتمعان.", "links": [{"ref": "3:195", "q": "﴿فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم﴾", "en": "No deed is lost", "ar": "لا يضيع عمل عامل"}, {"ref": "18:30", "q": "﴿إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا﴾", "en": "The same promise", "ar": "الوعد نفسه"}], "v": 1, "p": 333, "pe": 334, "sid": 334},
  {"a": [144, 144], "h": "\"A qibla that will please you\" — when Allah moves the heart toward what He is about to do", "hAr": "﴿فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ﴾ — حين يحرّك الحقّ القلب نحو ما يريد فعله", "said": "قيل لم يقصد بذلك أنك كنت ساخطا، وإنما كان - عليه السلام - يحركه السر، ويعلم بما يلقى في روعه أن الله تعالى يريد تغييرا في القبلة، وكان يتشوفه ... وقول مجاهد وابن زيد، أحب النبي عليه السلام التوجه إلى الكعبة مخالفة لليهود وقول ابن عباس فإنه أحبها اقتداء بإبراهيم عليه السلام وقول الزجاج إنه أحبها لاستدعاء العرب بها إلى الإسلام فكلها صحيحة إذ لا منافاة بين هذه الإرادات، وهذه منزلة يشير إليها أولو الحقائق ويذكرون أنها فوق التوكل، لأن قاصية المتوكل الاستسلام لما يجري عليه من القضاء كأعمى يقوده بصير ... وهذه المنزلة هي أن يحرك الحق سره بما يريده فعله", "en": "Was the Prophet ﷺ displeased with facing Jerusalem, that he was promised \"a qibla that will please you\"? No. His inner self was being stirred: from what was cast into his heart he knew that Allah meant to change the qibla, and he longed for it — \"We see your face turning toward the sky\", looking out for the revelation. Why did he love the Ka'bah? To be distinct from those who rejected him (Mujahid, Ibn Zayd); to follow Ibrahim (Ibn 'Abbas); to draw the Arabs to Islam (az-Zajjaj). All are true; one wish does not exclude another.\nAr-Raghib sees here a station that the people of inner realities describe as higher than trust (tawakkul). The farthest a trusting person goes is to surrender to whatever the decree brings — like a blind man led by one who can see. This station is higher: Allah Himself stirs the servant's heart toward what He is about to do. Sometimes that comes by revelation from outside — as Ibrahim was told \"submit\" — and sometimes by inspiration from within, as Musa's mother was inspired. (It is also said the verse shows his courtesy: he waited, and did not ask.)", "ar": "هل كان ﷺ ساخطًا توجّهه إلى بيت المقدس حتى قيل ﴿فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ﴾؟ لا؛ وإنما كان يتحرّك سرّه، ويعلم بما يُلقى في روعه أن الله يريد تغيير القبلة، فكان يتشوّفه — و﴿تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ﴾: تطلّعك إلى الوحي. وأقوالهم في سبب حبّه الكعبة — مخالفة اليهود (مجاهد وابن زيد)، والاقتداء بإبراهيم (ابن عباس)، واستدعاء العرب إلى الإسلام (الزجّاج) — كلّها صحيحة، إذ لا منافاة بين هذه الإرادات.\nوهذه منزلةٌ يشير إليها أولو الحقائق ويذكرون أنها فوق التوكّل: فقاصية المتوكّل الاستسلام لما يجري عليه من القضاء كأعمى يقوده بصير؛ وهذه المنزلة أن يحرّك الحقّ سرّه بما يريد فعله — ربما بوحيٍ من خارج، كقوله لإبراهيم ﴿أَسۡلِمۡۖ﴾، وربما بإلهامٍ من باطن، كما أوحى إلى أمّ موسى. (وقيل: فيه تنبيهٌ على حسن أدبه ﷺ: انتظر ولم يسأل.)", "links": [{"ref": "93:5", "q": "﴿وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ﴾", "en": "\"A qibla that will please you\" — the same care for his pleasure", "ar": "«قبلةً ترضاها» — والعناية نفسها برضاه"}, {"ref": "28:7", "q": "﴿وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ﴾", "en": "Inspiration from within", "ar": "الإلهام من الباطن"}, {"ref": "2:131", "q": "﴿إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾", "en": "Revelation from outside", "ar": "الوحي من خارج"}], "v": 1, "p": 334, "pe": 335, "sid": 335},
  {"a": [144, 144], "h": "\"Turn your face\" — then \"turn your faces\": why the command came twice", "hAr": "﴿فَوَلِّ وَجۡهَكَ﴾ ثم ﴿فَوَلُّواْ وُجُوهَكُمۡ﴾ — لماذا جاء الأمر مرّتين", "said": "قيل: لما تضمن كتبهم من ذكر النبي- عليه السلام-، وعلمهم أن عادة الله أن يخص كل رسول من أولي العزم بقبلة غير قبلة من تقدمه ... قيل: أما خطابه الخاص أولا، فتشريفا له، وإيجابا لرغبته وإنجازا لوعده، وأما خطابه العام بعده، فلأنه، كان يجوز أن يعتقد أن هذا أمر قد خص عليه السلام به كما خص بقوله: ﴿قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا﴾، ولأنه لما كان تحويل القبلة أمرا له خطر خصهم بخطاب مفرد ليكون ذلك أبلغ ... ولأن في الخطاب العام تعليق حكم آخر به، وهو أنه لا فرق بين القريب والبعيد في وجوب التوجه (إلى الكعبة)", "en": "\"Those who were given the Book know it is the truth from their Lord\" — how? Because their books spoke of the Prophet ﷺ, and they knew it was Allah's way to give each of the great messengers a qibla other than that of the one before him.\nWhy address him alone first — \"turn your face\" — and then everyone — \"turn your faces\"? The first honours him, answers his longing and fulfils the promise just made. The second was needed because the command might otherwise be thought to be his alone, like \"stand in prayer through the night, except a little\". And because changing the qibla was a weighty matter, they were given their own address, to make it stronger — as a ruler who sends a governor an important order that concerns everyone likes to address the people directly too, so it lands with more force and honours them. And the general address carries a further ruling: near or far from the Ka'bah, everyone must face it.", "ar": "﴿وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ﴾: من أين علموا؟ لما تضمّنته كتبهم من ذكر النبي ﷺ، ولعلمهم أن عادة الله أن يخصّ كلّ رسولٍ من أولي العزم بقبلةٍ غير قبلة من تقدّمه.\nولماذا خاطبه أوّلًا ﴿فَوَلِّ وَجۡهَكَ﴾ ثم عمّ ﴿فَوَلُّواْ وُجُوهَكُمۡ﴾؟ الخطاب الخاصّ أوّلًا تشريفٌ له، وإيجابٌ لرغبته، وإنجازٌ لوعده؛ والعامّ بعده لأنه قد يُعتقد أن الأمر خاصٌّ به كما خُصّ بقوله ﴿قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا﴾؛ ولأن تحويل القبلة أمرٌ ذو خطر فخصّهم بخطابٍ مفرد ليكون أبلغ — كالسلطان إذا خاطب واليه بأمرٍ ذي بالٍ يعمّ الرعيّة أحبّ أن يخصّهم بخطابٍ مفرد ليكون أوقع عندهم وأشرف لهم —؛ ولأن في الخطاب العامّ حكمًا آخر: لا فرق بين القريب والبعيد في وجوب التوجّه إلى الكعبة.", "links": [{"ref": "73:2", "q": "﴿قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا﴾", "en": "A command meant for him alone", "ar": "أمرٌ خاصٌّ به"}, {"ref": "2:146", "q": "﴿ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ﴾", "en": "They knew — as they know their own sons", "ar": "يعرفونه كما يعرفون أبناءهم"}], "v": 1, "p": 335, "pe": 336, "sid": 336},
  {"a": [145, 145], "h": "\"Nor will you follow their qibla\" — whoever truly arrives does not turn back", "hAr": "﴿وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ﴾ — من وصل حقًّا لا يرجع", "said": "وقوله: ﴿وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ﴾، أي لا يكون ذلك منك، فمحال أن من عرف الله حق معرفته يرتد، وقد قيل: (ما رجع من يرجع إلا من الطريق)، أي: \" ما أخل بالإيمان إلا من لم يصل إليه حق الوصول \" ... إن قيل: فقد يوجد من يحصل له معرفة ثم يرتد؟ قيل: إن الذي يقدر أنه معرفة، وهو ظن متصور بصورة العلم، فأما أن يتحصل العلم الحقيقي ثم يعقبه الارتداد فمحال ولم يعن بهذه المعرفة ما جعله الله تعالي للإنسان بالفطرة، فإن ذلك كشررة تخمد إذا لم تتوقد ... فإن الله تعالى يحذر نبيه من اتباع الهوى أكثر مما يحذر غيره [لأن] المنزلة الرفيعة إلى تجديد الإنذار عليه أحوج", "en": "\"Even if you brought them every sign, they would not follow your qibla\" — though some of them did believe? It is said of them as a whole, not of every one; as one can say \"they did not believe — though some of them did\" without contradiction.\n\"Nor will you follow their qibla\": it will not happen, because it is impossible that one who knows Allah as He should be known should turn back. As it was said, \"no one turns back except from the road\" — no one abandons faith except someone who never truly arrived. Does not someone sometimes gain knowledge and then leave? What he had was an opinion wearing the form of knowledge; real knowledge followed by apostasy is impossible. (He does not mean the knowledge given by the fitrah: that is like a spark, which dies if it is not kindled.)\nWhy is the Prophet ﷺ himself warned against their desires, again and again? Not because the words are \"really\" for the community: Allah warns His Prophet about desire more than anyone, because the higher the rank, the more it needs renewed warning to keep it — as a polished mirror needs the most care, since a little rust shows most on it.", "ar": "﴿وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ﴾ وقد آمن منهم فريق؟ قيل: حكمٌ على الكلّ لا على الأبعاض، كما تقول: ما آمنوا، ولكن آمن بعضهم، فلا تنافي.\nو﴿وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ﴾: لا يكون ذلك منك، فمحالٌ أن يرتدّ من عرف الله حقّ معرفته؛ وقد قيل: «ما رجع من رجع إلا من الطريق»، أي ما أخلّ بالإيمان إلا من لم يصل إليه حقّ الوصول. فإن قيل: قد يحصل لإنسانٍ معرفةٌ ثم يرتدّ؟ قيل: ما يُقدَّر أنه معرفةٌ ظنٌّ متصوّرٌ بصورة العلم، وأمّا أن يحصل العلم الحقيقيّ ثم يعقبه الارتداد فمحال. (ولم يُرد المعرفة التي جعلها الله للإنسان بالفطرة، فتلك كشررةٍ تخمد إذا لم تُوقَد.)\nولماذا حُذّر النبي ﷺ من أهوائهم مرّةً بعد مرّة؟ ليس لأن الخطاب له والمراد أمّته فقط، بل لأن الله يحذّر نبيّه من اتّباع الهوى أكثر ممّا يحذّر غيره: فالمنزلة الرفيعة إلى تجديد الإنذار أحوج حفظًا لها — كالمرآة المجلوّة، حقّها أن يُتعهّد صفاؤها أكثر، إذ القليل من الصدأ عليها أظهر.", "links": [{"ref": "14:27", "q": "﴿يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ﴾", "en": "Knowledge that truly arrives stays", "ar": "المعرفة الواصلة ثابتة"}, {"ref": "17:74", "q": "﴿وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا﴾", "en": "The Prophet warned most of all", "ar": "النبي أشدّ الناس تحذيرًا"}, {"ref": "2:120", "q": "﴿وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ مِنَ ٱلۡعِلۡمِ﴾", "en": "The same warning, twenty-five verses earlier", "ar": "التحذير نفسه قبل خمسٍ وعشرين آية"}], "v": 1, "p": 336, "pe": 337, "sid": 337},
  {"a": [146, 146], "h": "\"They know him as they know their own sons\" — why sons, and not themselves", "hAr": "﴿يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ﴾ — لماذا الأبناء لا أنفسهم", "said": "آتيناهم أبلغ من قوله: (أوتوا)، فإن (أوتوا) قد يستعمل فيمن لم يكن له قبول، وآتيناهم أكثر ما جاء فيمن له قبول نحو: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ﴾ ... وإنما قال: ﴿كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ﴾ ولم يقل أنفسهم، لأن الإنسان لا يعرف نفسه إلا بعد انقضاء برهة من دهره، ويعرف ولده من حين وجوده، ثم في ذكر الابن، ما ليس في ذكر النفس، فإن الإنسان عصارة ذاته ونسخة صورته، وإنما قال: ﴿لَيَكۡتُمُونَ ٱلۡحَقَّ﴾ ولم يقل يكتمونه، لأن في كتمان أمره كتمانه الحق جملة، وزاد في ذمهم بقوله: ﴿وَهُمۡ يَعۡلَمُونَ﴾", "en": "\"Those to whom WE gave the Book\" is stronger than \"those who were given the Book\": \"were given\" can be said of people who did not accept what they received; \"We gave them\" is mostly said of those who did — \"those are the ones to whom We gave the Book, judgement and prophethood\".\n\"They recognise it\" — the prophethood mentioned just before as \"the knowledge that has come to you\"; or the Prophet ﷺ himself, \"whom they find written with them\"; or that the turn to the Ka'bah is true. These are one: knowing the Messenger, knowing that he speaks the truth, and knowing that what he commands about the qibla is right, go together.\nWhy \"as they know their sons\", not \"as they know themselves\"? A person does not know himself until a stretch of his life has passed, but he knows his child from the day it is born; and there is something in a son that \"self\" does not carry — a son is the pressed essence of a man's being and a copy of his form.\n\"They hide the truth\" — not \"hide it\": hiding his matter is hiding the truth as a whole. \"While they know\" adds to the blame: one who sins in ignorance is not like one who sins knowingly.", "ar": "﴿أَتَيۡنَٰهُم﴾ أبلغ من «أوتوا»: فـ«أوتوا» قد يُستعمل فيمن لم يكن له قبول، و«آتيناهم» أكثر ما جاء فيمن له قبول، نحو: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ﴾.\nو﴿يَعۡرِفُونَهُۥ﴾: العلم الذي هو النبوّة المذكورة في ﴿مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ﴾، أو النبي ﷺ الذي ﴿يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ﴾، أو أن التوجّه إلى الكعبة حقّ؛ وهي متلازمة: معرفة الرسول، ومعرفة صدقه، وصحّة ما يأمر به من أمر القبلة.\nولماذا ﴿كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ﴾ ولم يقل «أنفسهم»؟ لأن الإنسان لا يعرف نفسه إلا بعد انقضاء برهةٍ من دهره، ويعرف ولده من حين وجوده؛ ثم في ذكر الابن ما ليس في ذكر النفس، فالابن عصارة ذات أبيه ونسخة صورته.\nو﴿لَيَكۡتُمُونَ ٱلۡحَقَّ﴾ ولم يقل «يكتمونه»: لأن في كتمان أمره كتمانَ الحقّ جملة. وزاد في ذمّهم بقوله ﴿وَهُمۡ يَعۡلَمُونَ﴾: فليس مرتكب الذنب عن جهلٍ كمرتكبه عن علم.", "links": [{"ref": "6:20", "q": "﴿ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ﴾", "en": "The same words in al-An'am", "ar": "الكلمات نفسها في الأنعام"}, {"ref": "7:157", "q": "﴿ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ﴾", "en": "What they found written", "ar": "ما وجدوه مكتوبًا عندهم"}, {"ref": "6:89", "q": "﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ﴾", "en": "\"We gave them\" — said of those who accepted", "ar": "«آتيناهم» فيمن قبِل"}], "v": 1, "p": 337, "pe": 338, "sid": 338},
  {"a": [147, 147], "h": "\"Do not be among the doubters\" — not a ban on doubt, but a call to the knowledge that ends it", "hAr": "﴿فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ﴾ — ليس نهيًا عن الشكّ، بل حثٌّ على المعرفة التي تزيله", "said": "وبين أن كل حق هو من الله تعالى، إما بإبداعه وإيجاده وصنعه، وإما بأمره وإما توفيقه، وقوله: ﴿فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ﴾ ليس بنهي عن الشك، إذ كان ذلك ليس بقصد من الشاك، بل هو حث على اكتساب المعارف المزيلة للشك واستعمالها، وعلى ذلك قوله تعالى: ﴿إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾", "en": "Imtira', \"doubting\", comes from stroking a camel's udder to draw its milk; the doubter is the one who keeps going back and forth over a question.\n\"The truth is from your Lord\": every truth is from Allah — by His originating and making, by His command, or by His enabling.\n\"So do not be among the doubters\" is not a prohibition of doubt as such — no one doubts on purpose. It urges the acquiring of the knowledge that removes doubt, and the using of it; as Nuh was told, \"I counsel you not to be among the ignorant\". The remedy for doubt is to learn.", "ar": "«الامتراء» من «مريتُ الناقة» إذا مسحتَ ضرعها لتدرّ، واستُعير «الممتري» للمتردّد.\nو﴿ٱلۡحَقُّ مِن رَّبِّكَ﴾: كلّ حقٍّ من الله: إمّا بإبداعه وإيجاده وصنعه، وإمّا بأمره، وإمّا بتوفيقه.\nو﴿فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ﴾ ليس نهيًا عن الشكّ — فالشاكّ لا يقصد الشكّ —، بل حثٌّ على اكتساب المعارف المزيلة للشكّ واستعمالها، كقوله لنوح: ﴿إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾. فدواء الشكّ التعلّم.", "links": [{"ref": "10:94", "q": "﴿فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ﴾", "en": "The remedy for doubt: ask and learn", "ar": "دواء الشكّ: السؤال والتعلّم"}, {"ref": "11:46", "q": "﴿إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾", "en": "The same kind of counsel", "ar": "من جنس هذه الموعظة"}, {"ref": "3:60", "q": "﴿ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ﴾", "en": "The same words in Al 'Imran", "ar": "الكلمات نفسها في آل عمران"}], "v": 1, "p": 338, "pe": 338, "sid": 339},
  {"a": [148, 148], "h": "\"Each has a direction he turns to — so race to good deeds\"", "hAr": "﴿وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ﴾", "said": "أي: لكل أمة، وقيل لكل نبي وجهته، وقيل قبلة، وقيل: شريعة، وذلك في المعنى واحد ... وقيل: معنى: ﴿وَلِكُلّٖ وِجۡهَةٌ﴾ أي للناس كلهم الآن وجهة، وهي الإسلام تنبيها أن الأديان به نسخت، نحو: ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾، وقوله: ﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ﴾ ... وقوله: ﴿أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ﴾ يعني أي شغل تحريتم، وحيثما صرفتم، وأي معبود اتخذتم فإنكم مجموعون ومحاسبون عليها", "en": "\"Each has a direction\": every nation — or every prophet — has its direction: its qibla, its law; in meaning these are one. \"He turns to it\": Allah turns each to it, or each turns himself to it. Another reading: for all people NOW there is one direction, Islam — a pointer that the earlier religions were superseded by it: \"the religion with Allah is Islam\", \"whoever seeks a religion other than Islam, it will not be accepted from him\".\n\"Race one another to good deeds\" — as in \"hasten to forgiveness from your Lord\".\n\"Wherever you may be, Allah will bring you all together\": whatever work you gave yourselves to, wherever you turned, whatever you took to worship — you will be gathered, and asked about it.", "ar": "﴿وَلِكُلّٖ وِجۡهَةٌ﴾: لكلّ أمّةٍ — أو لكلّ نبيٍّ — وجهته: قبلته أو شريعته، والمعنى واحد. و﴿هُوَ مُوَلِّيهَاۖ﴾: الله مولّيه إيّاها، أو كلٌّ مولٍّ وجهه إليها. وقيل: للناس كلّهم الآن وجهةٌ واحدة هي الإسلام، تنبيهًا على أن الأديان نُسخت به: ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾، ﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ﴾.\nو﴿فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ﴾ كقوله: ﴿وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ﴾.\nو﴿أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ﴾: أيَّ شغلٍ تحرّيتم، وحيثما انصرفتم، وأيَّ معبودٍ اتّخذتم، فإنكم مجموعون ومحاسَبون عليه.", "links": [{"ref": "5:48", "q": "﴿لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ﴾", "en": "Each nation its law", "ar": "لكلّ أمّةٍ شرعة"}, {"ref": "3:85", "q": "﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ﴾", "en": "One direction for all, now", "ar": "وجهةٌ واحدة للجميع الآن"}, {"ref": "3:133", "q": "﴿وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ﴾", "en": "Racing to good", "ar": "المسابقة إلى الخير"}], "v": 1, "p": 339, "pe": 339, "sid": 340},
  {"a": [148, 148], "h": "Every honest calling is a road to Allah — the farmer, the miller, the scholar", "hAr": "كلّ عملٍ صالحٍ طريقٌ إلى الله — الزارع والطحّان والعالم", "said": "وفي الآية قول آخر، وهو أن الله تعالى قيض الناس في أمور دنياهم وأخراهم لأحوال متفاوتة، وجعل بعضهم أعوان بعض فيها، فواحد يزرع، وآخر يطحن، وآخر يخبز وكذلك في أمر الدين، واحد يجمع الحديث، وواحد يطلب الفقه، والثالث يطلب الأصول وهم في الظاهر مختارون وفي الباطن مسخرون وإليه أشار النبي بقوله: \" كل ميسر لما خلق له \" ... فبين أن لكل طريقا إذا تحرى فيه وجه الله تعالى وعلى ذلك قوله: ﴿لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ﴾", "en": "Another reading of \"each has a direction he turns to\": Allah has set people, in the affairs of this world and the next, to different tasks, and made them helpers of one another. One farms, another grinds, another bakes. So too in religion: one gathers hadith, another studies law, another the foundations. Outwardly each chose his path; inwardly each was made for it — as the Prophet ﷺ said, \"each is eased toward what he was created for\".\nAnd Allah has made for every one of them a way to reach Him, if he attends to what is his to do and fulfils the trust in it. A righteous man, asked why people's work differs so, answered that each of these is a road that reaches Allah — He wanted every road peopled with His servants. So every calling is a road, if one seeks the Face of Allah in it.\nThis is how ar-Raghib sees ordinary life: not a distraction from religion, but one of its roads.", "ar": "وفي الآية قولٌ آخر: أن الله قيّض الناس في أمور دنياهم وآخرتهم لأحوالٍ متفاوتة، وجعل بعضهم أعوان بعض: فواحدٌ يزرع، وآخر يطحن، وآخر يخبز؛ وكذلك في أمر الدين: واحدٌ يجمع الحديث، وآخر يطلب الفقه، وثالثٌ يطلب الأصول؛ وهم في الظاهر مختارون وفي الباطن مسخَّرون، وإليه أشار النبي ﷺ بقوله: «كلٌّ ميسَّرٌ لما خُلق له».\nوجعل للكلّ سبيلًا إلى الوصول إليه إذا راعى ما هو بصدده وأدّى الأمانة فيه. وسُئل بعض الصالحين عن تفاوت الناس في أعمالهم، فأجاب بأن كلًّا منها طريقٌ إلى الله يوصل إليه، أراد أن يعمره بعباده. فلكلٍّ طريقٌ إذا تحرّى فيه وجه الله: ﴿لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ﴾.\nوهكذا ينظر الراغب إلى الحياة العاديّة: ليست شاغلًا عن الدين، بل طريقٌ من طرقه.", "links": [{"ref": "43:32", "q": "﴿نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ﴾", "en": "Livelihoods divided among people", "ar": "المعايش مقسومةٌ بين الناس"}, {"ref": "28:77", "q": "﴿وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾", "en": "Seeking the next world in what you were given", "ar": "ابتغاء الآخرة فيما أوتيت"}, {"ref": "2:128", "q": "﴿رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ﴾", "en": "The same thought: the world needs every calling", "ar": "الفكرة نفسها: الدنيا تحتاج كلّ الأعمال"}], "v": 1, "p": 339, "pe": 339, "sid": 340},
  {"a": [149, 149], "h": "Why \"turn your face\" is repeated — three reasons for the new qibla, each with its command", "hAr": "لماذا تكرّر ﴿فَوَلِّ وَجۡهَكَ﴾ — ثلاث علل للقبلة الجديدة، مع كلٍّ أمرُها", "said": "إن قيل: ما وجه تكرير ﴿فَوَلِّ وَجۡهَكَ﴾ قيل: إعادة ذلك لحكمة لطيفة، وهو أنه ذكر لتغيير القبلة ثلاث علل من قوله: ﴿سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ﴾ إلى قوله: ﴿وَلَعَلَّكُمۡ تَهۡتَدُونَ﴾ - الأولى: إكرامه تعالى نبيه - عليه السلام- إن ولاه قبلة أبيه إبراهيم ابتغاء مرضاته، وهو قوله: ﴿قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ﴾ والثانية: إخباره أن لكل صاحب دعوة قبلة وهو قوله: ﴿وَلِكُلّٖ وِجۡهَةٌ﴾، والثالثة: قطع حجة معانديه وهو قوله: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ﴾، فقرن بذكر كل علة معلولها الذي هو الفرض، وذلك قوله: ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ﴾ كقولك: إن هذا فرض لسبب كذا، وفرض لسبب كذا", "en": "\"Turn your face toward the Sacred Mosque\" comes three times in a few verses. Why? Ar-Raghib: for a fine reason. Between \"the foolish will say\" and \"that you may be guided\", Allah gives three reasons for the change of qibla:\n1. to honour His Prophet ﷺ by turning him to the qibla of his father Ibrahim, to please him — \"We see your face turning toward the sky\";\n2. to tell him that every bearer of a message has a qibla of his own — \"each has a direction\";\n3. to cut off the argument of his opponents — \"so that people will have no argument against you\".\nWith each reason He set down its consequence, the command itself — as one says: \"this is required for such a reason, and required for such a reason\". That is more telling than the view that the command was only repeated because the passage grew long.\n\"Your Lord\" in the first, \"Allah\" in the warning: \"Lord\" when He is inviting us to see His wisdom in His acts — the name that speaks of His favours, through which the Giver is known; \"Allah\" when He warns — the name that speaks of worship, whose neglect brings punishment.", "ar": "لماذا تكرّر ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ﴾؟ قال الراغب: لحكمةٍ لطيفة: ذكر لتحويل القبلة — من ﴿سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ﴾ إلى ﴿لَعَلَّكُمۡ تَهۡتَدُونَ﴾ — ثلاث علل:\n١. إكرامه نبيّه ﷺ بأن ولّاه قبلة أبيه إبراهيم ابتغاء مرضاته: ﴿قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ﴾؛\n٢. إخباره أن لكلّ صاحب دعوةٍ قبلة: ﴿وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ﴾؛\n٣. قطع حجّة معانديه: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ﴾.\nفقرن بكلّ علّةٍ معلولها الذي هو الفرض — ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ﴾ —، كما تقول: هذا فرضٌ لسبب كذا، وفرضٌ لسبب كذا؛ وهذا أبلغ من قول من قال: أُعيد لطول القصّة.\nوخصّ الأوّل بلفظ «الربّ» والثاني بلفظ «الله»: لأنه في الأوّل ينبّه على الاستدلال بأفعاله على حكمته، فذكر «الربّ» المقتضي للنعم التي يُستدلّ بها على المنعم؛ ولمّا انتهى إلى الوعيد ذكر «الله» المقتضي للعبادة التي من أخلّ بها استحقّ أليم العقاب.", "links": [{"ref": "2:144", "q": "﴿قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ﴾", "en": "The first reason: honouring the Prophet", "ar": "العلّة الأولى: إكرام النبي ﷺ"}, {"ref": "2:148", "q": "﴿وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ﴾", "en": "The second: every message has its qibla", "ar": "الثانية: لكلّ دعوةٍ قبلة"}, {"ref": "2:150", "q": "﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ﴾", "en": "The third: no argument left", "ar": "الثالثة: قطع الحجّة"}], "v": 1, "p": 340, "pe": 340, "sid": 341},
  {"a": [150, 150], "h": "\"Wherever you are, turn your faces toward it\" — with body and heart, or with the heart alone", "hAr": "﴿وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ﴾ — بالقلب والبدن، أو بالقلب وحده", "said": "فإن قيل: لم كرر قوله: ﴿وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ﴾، قيل: حث بأحدهما على التوجه نحو القبلة بالقلب والبدن في أي مكان حصل الإنسان نائيا كان عنها أو دانيا منها، وذلك حال الاختيار والتمكن، وحث بالآخر على التوجه بالقلب نحوه عند اشتباه القبلة ... وفي صلاة النافلة في حال المسير في السفر وعلى الراحلة", "en": "\"Wherever you are, turn your faces toward it\" also comes twice (2:144 and here). Ar-Raghib: one urges facing the qibla with heart and body wherever a person is, far from it or near — when he is free to choose and able; the other urges facing it with the heart when the body cannot: when the direction of the qibla is unclear, and in a voluntary prayer on a journey, riding.", "ar": "﴿وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ﴾ تكرّر أيضًا (١٤٤ وهنا): فحثّ بأحدهما على التوجّه نحو القبلة بالقلب والبدن في أيّ مكانٍ كان الإنسان، نائيًا عنها أو دانيًا منها، وذلك في حال الاختيار والتمكّن؛ وحثّ بالآخر على التوجّه إليها بالقلب عند اشتباه القبلة، وفي صلاة النافلة حال المسير في السفر على الراحلة.", "links": [{"ref": "2:144", "q": "﴿وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ﴾", "en": "The first time: heart and body", "ar": "المرّة الأولى: بالقلب والبدن"}, {"ref": "2:115", "q": "﴿وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾", "en": "Facing Him with the heart, when the direction is lost", "ar": "التوجّه إليه بالقلب حين تخفى الجهة"}], "v": 1, "p": 341, "pe": 341, "sid": 342},
  {"a": [150, 150], "h": "\"Do not fear them; fear Me — and I will complete My favour on you\": the gift and the earned", "hAr": "﴿فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ﴾ — الموهوب والمكتسب", "said": "قيل: الحجة ههنا موضوعة موضع الاحتجاج نحو: ﴿حُجَّتُهُمۡ دَاحِضَةٌ﴾ ومعناه: لئلا يحتج عليكم أحد إلا وهو ظالم ... ويقولون: ما بالكم تصلون إليها تارة وإلى غيرها أخرى ... وإتمام نعمته هو أن نعم الله تعالى ضربان: أحدهما موهوب، والآخر مكتسب، فالموهوب: كجودة الحفظ والفهم وصحة البدن والجاه، وكل ذلك لا يستحق بحصوله الحمد، ولا بفواته الذم، والمكتسب كالعلم والعمل الصالح المتوصل بهما إلى الثواب وهو الإيمان، وبه يستحق المدح والذم، فبين تعالى أنه إذا ائتمرتم في أمر القبلة، وصلتم إلى الحالة التي يحصل لكم الخشية المشار إليها بقوله: ﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ﴾ فقد أتممت نعمتي عليكم", "en": "\"So that people will have no argument against you — except the wrongdoers among them\": is the wrongdoer granted an argument? No: \"argument\" here means arguing, as in \"their argument is void\". No one will argue against you except a wrongdoer. A sensible person aims only at what can be reached; a believer does not expect a proof to silence the obstinate, who do not mind upholding what is false. And what could the disbelievers have argued? All directions are equal to reason — \"wherever you turn, there is the Face of Allah\" — so Allah fixed one direction for them all, lest their facing differ and the disbelievers say \"why do you pray toward it one time and toward something else another?\"\n\"Do not fear them\" — do not keep an eye on them or feel shy before them — \"fear Me\".\n\"And that I may complete My favour on you\": Allah's favours are of two kinds. Some are given — a good memory, quick understanding, a healthy body, standing — and no one deserves praise for having them, or blame for lacking them. Others are earned — knowledge, and righteous action that leads to reward, which is faith — and it is for these that a person is praised or blamed. When you obey Him about the qibla and reach the fear of Allah that \"only the knowledgeable among His servants\" have, then He has completed His favour on you.", "ar": "﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ﴾: هل للظالم حجّة؟ «الحجّة» هنا بمعنى الاحتجاج، كقوله ﴿حُجَّتُهُمۡ دَاحِضَةٌ﴾: لئلا يحتجّ عليكم أحدٌ إلا وهو ظالم. والعاقل لا يقصد إلا غرضًا يمكن بلوغه؛ فالمؤمن لا يطمع أن يكفّ بالحجّة المعاندَ الذي لا يبالي بارتكاب الباطل. وأيّ حجّةٍ كانت لهم؟ الجهات سواءٌ في المعقول — ﴿فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾ —، فقصرهم على جهةٍ واحدة لئلا يختلف توجّههم فيحتجّ عليهم الكفّار بالاختلاف: ما بالكم تصلّون إليها تارةً وإلى غيرها أخرى؟\nو﴿فَلَا تَخۡشَوۡهُمۡ﴾: لا تراقبوهم ولا تستحيوا منهم، ﴿وَٱخۡشَوۡنِي﴾.\nو﴿وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ﴾: نِعَم الله ضربان: موهوبٌ — كجودة الحفظ والفهم وصحّة البدن والجاه —، ولا يستحقّ الإنسان بحصوله حمدًا ولا بفواته ذمًّا؛ ومكتسَبٌ — كالعلم والعمل الصالح المتوصَّل بهما إلى الثواب، وهو الإيمان —، وبه يُستحقّ المدح والذمّ. فإذا ائتمرتم في أمر القبلة، وبلغتم الخشية المشار إليها في قوله ﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ﴾، فقد أتمّ نعمته عليكم.", "links": [{"ref": "33:37", "q": "﴿وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ﴾", "en": "Fearing people instead of Allah", "ar": "خشية الناس دون الله"}, {"ref": "35:28", "q": "﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ﴾", "en": "The fear that completes the favour", "ar": "الخشية التي تتمّ بها النعمة"}, {"ref": "5:3", "q": "﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي﴾", "en": "The favour completed", "ar": "النعمة تامّة"}], "v": 1, "p": 341, "pe": 343, "sid": 342}
];
